import{_ as o,o as t,c as a,ah as s}from"./chunks/framework.B_OU15-2.js";const p=JSON.parse('{"title":"SystemVerilog Conformance and Deviations","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"guide/systemverilog-reference.md","filePath":"guide/systemverilog-reference.md"}'),n={name:"guide/systemverilog-reference.md"};function r(d,e,c,i,l,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="systemverilog-conformance-and-deviations" tabindex="-1">SystemVerilog Conformance and Deviations <a class="header-anchor" href="#systemverilog-conformance-and-deviations" aria-label="Permalink to &quot;SystemVerilog Conformance and Deviations&quot;">​</a></h1><p>For setup and a first simulation, start with <a href="./systemverilog.html">SystemVerilog Support</a>.</p><h2 id="what-is-supported" tabindex="-1">Baseline: IEEE 1800-2023 <a class="header-anchor" href="#what-is-supported" aria-label="Permalink to &quot;Baseline: IEEE 1800-2023 {#what-is-supported}&quot;">​</a></h2><p>Celox implements SystemVerilog as specified by IEEE Std 1800™-2023. This page does not restate the standard. It organizes every difference into five categories:</p><ol><li><strong>Unsupported features</strong> — entire constructs or clauses not implemented and rejected at compile time.</li><li><strong>Partially supported features</strong> — features where Celox implements a specific subset; each table states <strong>Supported</strong> and <strong>Not supported</strong> side by side.</li><li><strong>Narrow limitations</strong> — specific edge-case restrictions in features that otherwise follow the standard.</li><li><strong>Intentional deviations</strong> — split into <a href="#deviations-standard-code">deviations affecting standard-conforming code</a> and <a href="#deviations-nonstandard-code">permissive acceptance of non-standard code</a>.</li><li><strong>Implementation-defined choices and the Celox execution model</strong> — tool choices where the standard leaves behavior unspecified, plus Celox&#39;s Rust <code>Simulator</code> / <code>Simulation</code> split, host clocks, multiple top modules, checkpoints, memory files, mixed-language designs, and DPI-C registration.</li></ol><h3 id="conformance-scope-standard-vs-non-standard-code" tabindex="-1">Conformance scope: standard vs. non-standard code <a class="header-anchor" href="#conformance-scope-standard-vs-non-standard-code" aria-label="Permalink to &quot;Conformance scope: standard vs. non-standard code&quot;">​</a></h3><ul><li><strong>Standard-conforming code:</strong> Valid IEEE 1800-2023 code that does not rely on any construct, limit, or deviation listed on this page executes as the standard specifies — or, if a feature is unimplemented, fails at compile time with an <code>Unsupported</code> diagnostic naming the construct and its tracking issue (or the frontend roadmap <a href="https://github.com/celox-sim/celox/issues/88" target="_blank" rel="noreferrer">#88</a>) rather than silently mis-simulating. Any unlisted difference on valid standard code is a bug; please <a href="https://github.com/celox-sim/celox/issues" target="_blank" rel="noreferrer">file an issue</a>.</li><li><strong>Non-standard code (default mode vs. strict mode):</strong> Accepting non-standard code is less severe than mis-simulating valid standard code, so <strong>default mode</strong> intentionally accepts several common compatibility relaxations with warnings (see <a href="#deviations-nonstandard-code">Permissive acceptance of non-standard code</a> and <a href="./celox-toml.html#diagnostics"><code>[diagnostics]</code></a>). In <strong>strict mode</strong> (<code>strict = true</code> / <code>--strict</code> / <code>.strict(true)</code>), those compatibility diagnostics become errors; <strong>accepting any non-IEEE 1800-2023 code in strict mode (outside the explicit extensions documented below) is a bug</strong> — please <a href="https://github.com/celox-sim/celox/issues" target="_blank" rel="noreferrer">file an issue</a>.</li></ul><p>Measured conformance is published on the <a href="/celox/verification/">verification page</a>.</p><h2 id="what-is-not-supported" tabindex="-1">Unsupported features <a class="header-anchor" href="#what-is-not-supported" aria-label="Permalink to &quot;Unsupported features {#what-is-not-supported}&quot;">​</a></h2><p>These constructs and clauses are not implemented and are always rejected at compile time:</p><ul><li><strong>Verification and design-level blocks:</strong> <code>bind</code>, <code>checker</code>, <code>config</code>, user-defined primitives (UDP), and <code>specify</code> blocks. Clocking blocks are supported in part; see <a href="#clocking-blocks">Clocking blocks</a>. Covergroups are supported in part; see <a href="#covergroups">Coverage groups</a>.</li><li><strong>Unions and mixed array/container types:</strong> <code>tagged</code> unions, unpacked unions, packed union assignment patterns, fixed-size unpacked arrays of <code>chandle</code> (<code>chandle a[4]</code>, including via <code>typedef</code>), fixed-size unpacked arrays of dynamic containers (<code>int a[2][$]</code>, including via <code>typedef</code>), and dynamic containers of multidimensional fixed-size unpacked arrays (<code>int a[][2][3]</code>).</li><li><strong>Control flow:</strong> <code>disable</code> statements other than <code>disable fork</code>; <code>fork</code> inside declaration initializers, <code>final</code>, <code>always_comb</code>, and <code>always_ff</code> (no process scheduler in those contexts).</li><li><strong>Timing and system tasks:</strong> <code>wait_order</code>, and any unimplemented IEEE 1800-2023 or Annex D system task/function. Celox knows every standard name and reports unsupported ones by name wherever written, including in unused parameters and function bodies (e.g., <code>$q_initialize</code>).</li></ul><h2 id="partial-support" tabindex="-1">Partially supported features <a class="header-anchor" href="#partial-support" aria-label="Permalink to &quot;Partially supported features {#partial-support}&quot;">​</a></h2><p>For features with partial support, each table states both the <strong>Supported</strong> subset and what is <strong>Not supported</strong>.</p><h3 id="ports-and-gates" tabindex="-1">Ports, nets, <code>defparam</code>, and gate primitives <a class="header-anchor" href="#ports-and-gates" aria-label="Permalink to &quot;Ports, nets, `defparam`, and gate primitives {#ports-and-gates}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Wildcard <code>.*</code> port connections</strong> (<a href="https://github.com/celox-sim/celox/issues/442" target="_blank" rel="noreferrer">#442</a>)</td><td>Wildcard <code>.*</code> connections to modules defined in the SystemVerilog sources (including modules with interface ports)</td><td>Wildcard <code>.*</code> connections to a module defined outside the SystemVerilog sources (such as Veryl)</td></tr><tr><td><strong><code>ref</code> and <code>const ref</code> ports (23.3.3.2)</strong></td><td>ANSI and non-ANSI <code>ref</code> and <code>const ref</code> ports on modules and programs: packed/unpacked/struct/enum/<code>string</code>/<code>real</code>/class/container/<code>event</code> variables and unpacked-struct members, chained <code>ref</code> hierarchies, package variable actuals, <code>const ref</code> read-only enforcement, and IEEE 1800-2023 6.22.2 semantic type-equivalence checks</td><td>Top-level <code>ref</code> ports; connections to individual elements of unpacked arrays or dynamic containers; instance-array element-by-element slicing; queues with differing bounds; procedural <code>force</code>/<code>release</code> or <code>assign</code>/<code>deassign</code> targeting <code>ref</code> ports (or variables aliased by them); <code>ref</code> ports crossing a Veryl/SystemVerilog boundary</td></tr><tr><td><strong>Nets with multiple drivers (6.6.1–6.6.3)</strong></td><td>Continuous assignments within one module to <code>wire</code>, <code>tri</code>, <code>wand</code>, <code>triand</code>, <code>wor</code>, or <code>trior</code> nets (resolved per 6.6.1–6.6.3. In 2-state simulation, without X/Z literals). Continuous assignments and net declaration assignments to <code>wire</code> or <code>tri</code> resolve drive strengths (28.12)</td><td>Multiple drivers across module instances (such as a tri-state bus across modules); drive strengths on <code>wand</code>, <code>triand</code>, <code>wor</code>, and <code>trior</code> with multiple drivers (28.12.4); <code>tri0</code>, <code>tri1</code>, and supply nets with several drivers; drivers calling a function with a data-dependent loop; in 2-state simulation, drivers with X or Z literals</td></tr><tr><td><strong>Undriven nets and <code>inout</code> ports</strong></td><td>Sub-module <code>inout</code> ports with one continuous driver on either side (e.g., <code>assign io = oe ? d : &#39;z;</code>); undriven bits of a net with an independent delay read <code>z</code></td><td>Top-module <code>inout</code> ports; internal nets without a driver (<a href="https://github.com/celox-sim/celox/issues/460" target="_blank" rel="noreferrer">#460</a>) except undriven bits of a net with an independent delay</td></tr><tr><td><strong>Gate and switch primitives (Clause 28)</strong></td><td><code>and</code>, <code>nand</code>, <code>or</code>, <code>nor</code>, <code>xor</code>, <code>xnor</code>, <code>buf</code>, <code>not</code>, <code>bufif0</code>, <code>bufif1</code>, <code>notif0</code>, and <code>notif1</code> without delays or drive strengths, single or in 1D instance arrays</td><td>All other gate and switch primitives (switches, pull sources); gate delays, drive strengths, and multidimensional gate instance arrays (<a href="https://github.com/celox-sim/celox/issues/457" target="_blank" rel="noreferrer">#457</a>); a net that a three-state gate (<code>bufif0</code>, <code>bufif1</code>, <code>notif0</code> or <code>notif1</code>) drives has no other driver, as their L and H outputs resolve by strength (28.12.2)</td></tr><tr><td><strong><code>defparam</code> assignments</strong></td><td>Overriding a parameter of a direct child module instance of the module containing the <code>defparam</code> (including inside a generate block)</td><td>Paths through a child instance (<code>a.b.P</code>), paths starting at <code>$root</code>, elements of instance arrays, interface instances, and parameters of the statement&#39;s own scope</td></tr><tr><td><strong><code>let</code> declarations (11.12)</strong></td><td>Declarations among items of a module, interface, or program, expanded at each call</td><td><code>let</code> in a package, generate block, or procedural block; calls in a scope that redeclares a name used in the <code>let</code> body</td></tr></tbody></table><h3 id="hierarchical-references" tabindex="-1">Hierarchical references <a class="header-anchor" href="#hierarchical-references" aria-label="Permalink to &quot;Hierarchical references {#hierarchical-references}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Variables, nets, and continuous assignments</strong></td><td>Reads of nets and variables, procedural writes (including unpacked array elements and <code>string</code> variables/methods), members of a packed-struct variable or of an element of an array of packed structs, and continuous assignments driving another instance&#39;s variable (when its own module does not also drive it continuously or from <code>always_comb</code>)</td><td>Continuous assignments driving a net through a hierarchical name, or driving a variable that its own module also drives continuously or from <code>always_comb</code>; hierarchical references in port connections; named blocks; structure members of another scope other than packed structs or arrays of packed structs; <code>real</code> or class-typed signals; names starting inside a generate block relative to it</td></tr><tr><td><strong>Subroutine calls (23.8)</strong></td><td>Calling a task or function declared in another module&#39;s scope when it resolves to one specialization for every instance of the calling module</td><td>Subroutines whose formals, result, or named variables are <code>real</code>, <code>shortreal</code>, class, or <code>event</code> typed; two modules calling each other&#39;s subroutines</td></tr><tr><td><strong>Parameters (23.6)</strong></td><td>Reading an integral parameter or localparam of another instance (<code>u.N</code>) with at most one <code>[N-1:0]</code> packed dimension (values &gt; 128 bits must have no X/Z bits) as a run-time value</td><td>Non-integral or multi-packed-dimension hierarchical parameters; values &gt; 128 bits with X/Z bits; using a hierarchical parameter as an elaboration-time constant expression (A.8.4 <code>constant_primary</code>)</td></tr><tr><td><strong>Static subroutine variables (<code>f.v</code>, 23.6)</strong></td><td>Accessing a subroutine&#39;s static variable from a scope where <code>f</code> is visible by simple name (a method of the class or a base, or a subroutine of the design element)</td><td>Access through an instance, package, or named block; static variables of unpacked structure type</td></tr><tr><td><strong>Upward names from interface bodies (23.8)</strong></td><td>Resolving undeclared names in an interface instance body (including in tasks/functions called via a virtual interface) from the instantiating scope, when the name denotes objects of one type in every instance of the interface</td><td>Upward lookup when reached through an interface port, or inside an interface instance declared within another interface&#39;s body</td></tr></tbody></table><h3 id="interface-restrictions" tabindex="-1">Interfaces <a class="header-anchor" href="#interface-restrictions" aria-label="Permalink to &quot;Interfaces {#interface-restrictions}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Declarations</strong></td><td>Value and type parameters, header package imports, <code>localparam</code>, <code>typedef</code>, variables, nets, <code>assign</code>/<code>always_comb</code>/<code>always_ff</code>/generate logic, functions, tasks, and nested interface instances up to 64 levels</td><td>Implicit nets, <code>enum</code>, module instances, macros, and compiler directives inside an interface; recursive specializations or nesting beyond 64 levels; variable declaration initializers on members of an interface array; default lifetime (<code>interface automatic</code>) differing from the using module</td></tr><tr><td><strong>Modports and connections</strong></td><td><code>input</code> and <code>output</code> modport members, <code>import</code> functions/tasks, generic <code>interface</code> and <code>interface.mp</code> ports, explicit/implicit named connections (<code>.bus(bus)</code>, <code>.bus</code>), and read-only access through a port without a modport</td><td><code>inout</code>, <code>ref</code>, expression ports, <code>export</code>, and clocking modports; naming a modport in a connection when the receiving port declares none; writes through a port without a modport; member connections from a modport-less port to a non-ANSI module</td></tr><tr><td><strong>Dependencies, names, and identifiers</strong></td><td>Standard scoping within one compilation order and plain identifiers without <code>$</code></td><td>Member references in parameter, constant, type, or member declarations of an interface used through a port; <code>$unit</code> items used by an interface when a module in another file or earlier in the file uses it; references to implicit generate names (<code>genblk1</code>) and paths through generate blocks (<code>g.h.x</code>); declarations reusing an interface instance or port name; package names imported via an interface colliding with another imported package item or module declaration; user identifiers containing <code>$</code> or non-simple escaped identifiers in designs with interfaces (<code>$</code> is reserved for interface expansion)</td></tr></tbody></table><p>For static-variable storage of interface tasks and functions called across modules (<a href="https://github.com/celox-sim/celox/issues/3739" target="_blank" rel="noreferrer">#3739</a>), see <a href="#deviations-standard-code">Deviations affecting standard-conforming code</a>.</p><h3 id="virtual-interfaces" tabindex="-1">Virtual interfaces <a class="header-anchor" href="#virtual-interfaces" aria-label="Permalink to &quot;Virtual interfaces {#virtual-interfaces}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Declarations, parameters, and access</strong></td><td><code>virtual ifc</code>, <code>virtual ifc.mp</code>, and <code>virtual ifc#(P)</code> for interfaces with integral constant value parameters; variables, class properties, subroutine arguments/results, array/container elements, class type parameter values; reads/writes to variables; calling interface tasks and functions <em>(see storage note under <a href="#deviations-standard-code">Deviations affecting standard-conforming code</a>)</em></td><td>Virtual interfaces of interfaces with type parameters or non-integral-constant parameter values; clocking blocks and nested interface instances reached through a virtual interface; writes to nets through a virtual interface; <code>$bits</code> of an interface function call through a virtual interface in a package or class (works in a module; <a href="https://github.com/celox-sim/celox/issues/4056" target="_blank" rel="noreferrer">#4056</a>)</td></tr><tr><td><strong>Event controls and <code>wait</code></strong></td><td><code>@(...)</code> and <code>wait</code> through a virtual interface held in a static variable, a property of <code>this</code>, or a property of a statically held object; named-event waits <code>@(v.e)</code> and <code>@(v.e or other_event)</code> (waiting on the event denoted when the wait begins) and triggers</td><td><code>wait</code> through a virtual interface held by an automatic variable, subroutine argument, or class property of an automatically held object; event controls mixing a virtual-interface named event with other kinds of events (<code>@(v.e or v.d)</code>)</td></tr></tbody></table><h3 id="programs" tabindex="-1">Programs <a class="header-anchor" href="#programs" aria-label="Permalink to &quot;Programs {#programs}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Program declarations (Clause 24)</strong></td><td>Instantiated <code>program</code> blocks with ports and parameters; their <code>initial</code> procedures run in the reactive region set</td><td>Programs nested in modules; anonymous programs; uninstantiated programs as implicit top levels</td></tr></tbody></table><p>Program region and <code>$exit</code> differences are listed under <a href="#deviations-standard-code">Deviations affecting standard-conforming code</a>.</p><h3 id="unpacked-structures" tabindex="-1">Unpacked structures <a class="header-anchor" href="#unpacked-structures" aria-label="Permalink to &quot;Unpacked structures {#unpacked-structures}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Storage and contexts</strong></td><td>Module variables, procedural locals, non-<code>static</code>/non-<code>rand</code>/non-<code>const</code> class properties, dynamic container elements, and subroutine arguments (including <code>ref</code>) and return values</td><td>Module ports, nets, and parameters; <code>static</code>, <code>rand</code>, or <code>const</code> class properties</td></tr><tr><td><strong>Scalar and nested members</strong></td><td>Integral types, enums, <code>string</code>, class handles, packed structs, and nested unpacked structs (each keeping its own 2-state/4-state type)</td><td><code>real</code> / <code>shortreal</code> members</td></tr><tr><td><strong>Fixed-size array members</strong></td><td>Fixed-size unpacked arrays (including multidimensional and typedef&#39;d) of plain integral or packed-vector types, in module variables and procedural locals only</td><td>Fixed-size array members of enum, packed aggregate, <code>string</code>, handle, or unpacked struct type; declared initial values on fixed-size array members; structs with fixed-size array members as ports, class properties, subroutine interfaces, or dynamic container elements</td></tr><tr><td><strong>Dynamic container members (7.2.1)</strong></td><td>Dynamic array, queue, and associative array members (copied with the structure)</td><td>Declared initial values on container members; fixed-size arrays of dynamic containers (<code>int a[2][$]</code>); <code>%p</code> of a struct with a container member; fixed-size arrays of such structs; mutating a container member of a struct stored inside another container (<code>q[i].m.push_back(x)</code>, <code>q[i].m[j] = x</code>, <code>q[i].m = x</code> — read-only there)</td></tr><tr><td><strong>Fixed-size arrays of structs</strong></td><td>Module variables and procedural locals where every leaf member is integral, all leaves are 2-state or all are 4-state, and no member declares an initial value</td><td>Structs with <code>string</code>, handle, or dynamic-container members, mixed 2-state/4-state leaves, or member initial values; arrays of structs as ports, class properties, or subroutine interfaces</td></tr><tr><td><strong>Member initial values (7.2.2)</strong></td><td>Constant integral initializers on module variables, procedural locals, and class properties (resolved in the declaration scope)</td><td>Initializers on enum, non-integral, or array/container members; whole nested-struct member initializers; defaulted struct types in module ports, subroutine interfaces, or dynamic containers</td></tr></tbody></table><h3 id="procedural-force-and-assign" tabindex="-1">Procedural <code>force</code>/<code>release</code> and <code>assign</code>/<code>deassign</code> <a class="header-anchor" href="#procedural-force-and-assign" aria-label="Permalink to &quot;Procedural `force`/`release` and `assign`/`deassign` {#procedural-force-and-assign}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Construct</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Procedural <code>force</code> / <code>release</code> (10.6.2) — placement and targets</strong></td><td>Inside <code>initial</code>, <code>always</code> (runs as a process), and tasks; targets are packed integral module variables/nets (including via hierarchical names and interface instance/array members <code>u.bus[2].ready</code>), constant bit/part-selects or members, and constant-indexed elements (or constant selects/members) of fixed-size unpacked arrays of packed integrals <em>(variable selects and unpacked array elements are non-standard extensions — see <a href="#deviations-nonstandard-code">Permissive acceptance of non-standard code</a>; emits <code>forced_array</code> / <code>forced_specialization</code> warnings where applicable)</em></td><td>In functions, <code>final</code>, <code>always_comb</code>, <code>always_latch</code>, or <code>always_ff</code>; concatenations; selects with non-constant bounds; unpacked array slices; <code>real</code>, <code>string</code>, handle, or unpacked-struct targets; top-module input ports; targets also forced by host <code>Simulator::force</code>; interface members written by another instance through an interface port; unpacked arrays written by several edge-triggered processes; variables written by delayed NBAs; targets read and written by the same <code>always_comb</code>/<code>always_latch</code>/<code>always @*</code> block or assigned whole by an <code>always_comb</code> running as a process; overlapping forced parts when one force RHS reads a variable</td></tr><tr><td><strong>Procedural <code>force</code> / <code>release</code> — RHS expressions</strong></td><td>Constants, module/instance signals, static task variables/arguments (read when <code>force</code> executes), and <code>$urandom</code>/<code>$urandom_range</code> with constant arguments (drawn on execute and when a RHS variable changes)</td><td>Expressions with side effects, subroutine calls, or system functions other than <code>$urandom</code>/<code>$urandom_range</code> with constant arguments; expressions reading procedural block locals or automatic task variables</td></tr><tr><td><strong>Procedural <code>assign</code> / <code>deassign</code> (10.6.1)</strong></td><td>Inside <code>initial</code> and <code>always</code> (runs as a process), targeting a whole packed integral module variable with a side-effect-free, call-free expression over module signals <em>(see <a href="#deviations-standard-code">Deviations affecting standard-conforming code</a> for override timing on indirect writes)</em></td><td>In subroutines, <code>final</code>, <code>always_comb</code>, <code>always_latch</code>, or <code>always_ff</code>; concatenations, <code>real</code>, <code>string</code>, handle, unpacked, or procedural-block-local targets; targets also assigned by <code>always @*</code>; RHS with side effects, subroutine/system-function calls, or reads of procedural block locals</td></tr></tbody></table><p>Forcing an instance&#39;s input port forces that port rather than the connected net; a write to a forced target through a hierarchical name from a module that does not force it is not overridden; and a run-time-indexed write to a forced unpacked array preserves the forced bits of that element.</p><h3 id="continuous-assignment-delays" tabindex="-1">Delays <a class="header-anchor" href="#continuous-assignment-delays" aria-label="Permalink to &quot;Delays {#continuous-assignment-delays}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Form</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Intra-assignment timing (10.4.2)</strong></td><td>Delayed nonblocking assignments (<code>lhs &lt;= #constant rhs</code>) with integral constant delays or time literals in <code>initial</code> and ordinary <code>always</code> processes</td><td>Nonblocking intra-assignment event controls (<code>lhs &lt;= @(e) rhs</code>); non-constant delays; delayed NBAs outside <code>initial</code> and ordinary <code>always</code></td></tr><tr><td><strong>Continuous assignment delays (<code>assign #d</code>, <code>wire #d w = expr</code>)</strong> (<a href="https://github.com/celox-sim/celox/issues/444" target="_blank" rel="noreferrer">#444</a>)</td><td>One nonnegative integral constant or time literal on a scalar or packed integral target (including constant bit/part-select) with an integral RHS containing no subroutine calls</td><td>Rise/fall/turn-off delay lists; variable, negative, or unitless fractional real amounts; concatenated or aggregate destinations; dynamic destination selects; non-integral destinations; RHS containing subroutine calls</td></tr><tr><td><strong>Independent net delays (<code>wire #d w;</code>)</strong></td><td>One nonnegative integral constant or time literal on a scalar or packed integral net driven by static continuous assignments or supported logic gates (undriven bits read <code>z</code>)</td><td>Delayed nets in instance port connections; delayed <code>input</code> or <code>inout</code> ports; unpacked or non-integral delayed nets; drivers with dynamic destination selects</td></tr></tbody></table><h3 id="timing-controls" tabindex="-1">Event controls and waits <a class="header-anchor" href="#timing-controls" aria-label="Permalink to &quot;Event controls and waits {#timing-controls}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Construct</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>General <code>@(...)</code> event expressions</strong></td><td>Signals, <code>posedge</code>/<code>negedge</code>/<code>edge</code>, bit/part/dynamic selects, general expressions with pure functions, <code>iff</code> (in ordinary <code>always</code>/processes), and static virtual interfaces</td><td>Impure function calls in event expressions; reading a static task argument</td></tr><tr><td><strong>Class properties in <code>@(...)</code></strong></td><td>A bare property item such as <code>@(posedge h.p)</code>, optionally with an <code>iff</code> reading only constants and variables written solely by the waiting process</td><td>Class properties inside a larger expression, through a function, or in a container held by a property; an <code>iff</code> on a property item reading anything written outside the waiting process; an expression item, or an <code>iff</code> other than a 1-bit variable, in the same event list as a property item</td></tr><tr><td><strong><code>wait (condition)</code></strong></td><td>General expressions, static virtual interfaces, and class properties (re-checked on matching property stores; see <a href="#timing-semantics">Event scheduling</a>)</td><td>Conditions reading a static task argument, <code>rand_mode()</code>, or <code>constraint_mode()</code>; conditions over class properties that call a task or effectful function, or read time, a random number, a mailbox, or a process</td></tr><tr><td><strong>Fork-shared automatic locals</strong></td><td>Event expressions watching fork-shared automatic locals</td><td>Compound event expressions with mixed global/static dependencies, foreign calls, functions retaining scratch state, or implicit writes to a watched operand from a function, seed/plusargs result, or system task such as <code>$readmemh</code></td></tr><tr><td><strong><code>always_ff</code> event lists</strong></td><td>Single plain 1-bit signal edge (<code>@(posedge clk)</code>), clock plus asynchronous reset edge(s) tested in the body, and expression/member/bit/<code>edge</code> events (run as a timed process; see <a href="#celox-execution-model">Execution model</a>)</td><td><code>iff</code> qualifiers (<a href="https://github.com/celox-sim/celox/issues/452" target="_blank" rel="noreferrer">#452</a>); multi-bit edge signals; multiple edges without an asynchronous reset <em>(ordinary <code>always</code> supports these shapes as a timed process)</em></td></tr></tbody></table><h3 id="clocking-blocks" tabindex="-1">Clocking blocks <a class="header-anchor" href="#clocking-blocks" aria-label="Permalink to &quot;Clocking blocks {#clocking-blocks}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Declarations (14.3, 14.4)</strong></td><td>Named clocking blocks in modules and programs, with any clocking event (an edge, a named event, an <code>iff</code> guard); <code>input</code>, <code>output</code>, <code>input ... output</code> and <code>inout</code> clockvars of ports and of variables declared before the block; <code>default</code> skews; input skews <code>#1step</code>, <code>#0</code> and constant delays; output skews <code>#0</code>, <code>#1step</code> and constant delays; delays as integral constants, time literals and fixed-point literals (<code>#0.5</code>, in the time unit of the scope)</td><td><code>##</code> cycle delays and the default clocking they use (14.11, 14.12); <code>$global_clock</code> (14.14); edge skews; skews of other real-valued constants (<code>#D</code> of a <code>real</code> parameter); clockvars of unpacked structures, unpacked arrays and containers; clockvars of hierarchical expressions (14.5); property, sequence and <code>let</code> declarations in a clocking block; clocking blocks in generate blocks and in interfaces</td></tr><tr><td><strong>Events and sampling (14.10, 14.13, 14.15)</strong></td><td><code>@(cb)</code>, which wakes after the clocking event&#39;s Observed region; reading input clockvars, their selects and members; event controls on clockvars (<code>@(cb.x)</code>, <code>@(posedge cb.x[0])</code>)</td><td>—</td></tr><tr><td><strong>Synchronous drives (14.16)</strong></td><td><code>cb.x &lt;= e</code> and <code>cb.x[c] &lt;= e</code> with constant selects, executed at a clocking event or between events (maturing at the next one), in the Re-NBA region plus the output skew; of the drives of a bit that mature in one Re-NBA region only the last executed is driven, also where drives of different ranges overlap, and a drive executed at the clocking event is later than one executed before it (14.16.2)</td><td>Drives of selects with run-time indices; <code>##</code> in a drive; drives of nets; drives in a procedure whose own variable hides the clockvar&#39;s signal, or whose own declaration hides a name of the output skew</td></tr></tbody></table><h3 id="named-events" tabindex="-1">Named events and mailboxes <a class="header-anchor" href="#named-events" aria-label="Permalink to &quot;Named events and mailboxes {#named-events}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Named <code>event</code> (15.5)</strong></td><td>Scalar event variables, class properties, and subroutine arguments; <code>-&gt; e</code>, <code>-&gt;&gt; e</code>, <code>@e</code> / <code>@(e1 or e2)</code> (including expressions such as <code>obj.e</code> and virtual-interface events <code>v.e</code>), <code>wait (e.triggered)</code>, <code>e1 = e2</code>, <code>null</code>, and equality comparisons</td><td>Arrays of events; event ports; event members of unpacked structures; functions returning an <code>event</code>; triggers in <code>always_comb</code>/<code>always_latch</code>; <code>-&gt;&gt;</code> with a delay or event control; event controls mixing an event with signal changes or edges (<code>@(e or posedge clk)</code>); <code>triggered</code> combined with other operands or read via a function in <code>wait</code>; <code>wait_order</code></td></tr><tr><td><strong>Mailboxes (15.4)</strong></td><td>Parameterized <code>mailbox #(T)</code> / <code>std::mailbox #(T)</code> where <code>T</code> is an integral type up to 64 bits, <code>string</code>, or a class, <code>mailbox</code>, <code>semaphore</code>, <code>process</code>, or <code>event</code> handle</td><td>Typeless <code>mailbox</code> (without a type parameter); element types wider than 64 bits or outside the types listed</td></tr></tbody></table><h3 id="classes" tabindex="-1">Classes <a class="header-anchor" href="#classes" aria-label="Permalink to &quot;Classes {#classes}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Parameters and specializations (8.25)</strong></td><td>Value and type parameters (including typedef&#39;d enums/structs/unions, package and <code>$unit</code> classes, and forwarding a class&#39;s own 4-state/<code>string</code> parameters by name); interface classes (<code>implements</code> / <code>extends</code>)</td><td>Anonymous enum, struct, or union types as value or type parameters; named 4-state or <code>string</code> constants of a module or package as class parameter values; module-local classes as type arguments to package-class specializations</td></tr><tr><td><strong>Properties and member access</strong></td><td>2-state/4-state packed integrals, enums, <code>string</code>, class handles, <code>chandle</code>, virtual interfaces, named events, non-<code>const</code> dynamic containers, non-<code>static</code>/non-<code>rand</code>/non-<code>const</code> unpacked structs (without fixed-size array members), and 1D fixed-size array properties (see row below); bit/part-select reads on <code>[N-1:0]</code> properties (any declared range inside constraints)</td><td><code>real</code> properties; <code>const</code> dynamic container properties; packed-struct members of a property; selects of a member of an unpacked-struct property; bit/part-select reads outside constraints on properties not declared <code>[N-1:0]</code></td></tr><tr><td><strong>Fixed-size array properties</strong></td><td>Non-<code>static</code>, non-<code>randc</code> 1D fixed-size array properties with nonnegative <code>int</code> bounds; element access, assignment/comparison with another such property or a directly named array variable (for non-struct elements), and <code>[0:N-1]</code> constraint <code>foreach</code> / unpacked-struct locator methods</td><td><code>static</code> or <code>randc</code> fixed-size array properties; &gt; 1 unpacked dimension, negative bounds, or bounds outside <code>int</code>; assigning/comparing with arrays other than another such property or a directly named array variable (or any array variable for unpacked-struct elements); keyed assignment patterns; unpacked array concatenations containing an array item; slices; passing to <code>ref</code>/<code>output</code>/<code>inout</code> formals; constraint <code>foreach</code> or unpacked-struct locator methods when the range is not <code>[0:N-1]</code></td></tr><tr><td><strong>Assignments, arguments, and overrides</strong></td><td>Blocking assignments to properties; passing whole properties as <code>input</code> or <code>ref</code> arguments (see <a href="#reference-arguments">Reference arguments</a>); module classes overriding virtual methods of external classes when reading non-array integral module variables/ports or class handles</td><td>Nonblocking assignments to properties; properties as <code>output</code> or <code>inout</code> arguments; virtual method overrides of classes declared outside the module that read module variables/ports of other types (such as unpacked arrays), static variables, or call module subroutines reading module variables</td></tr><tr><td><strong>Virtual method dispatch (8.20)</strong></td><td>Calls and <code>$cast</code> dispatch on the class of the object in every scope, also for objects of classes of packages the calling scope does not use, and in the code of interface instances bound into such a scope</td><td>A virtual method call, in another scope, on an object of a class a module declares or of a specialization a module makes of a package class template: a fatal error naming the method, and the <code>$cast</code> of such an object fails</td></tr><tr><td><strong><code>$cast</code> (6.24.2)</strong></td><td>Dynamic <code>$cast</code> between class handles</td><td><code>$cast</code> to a variable that is not a class handle</td></tr></tbody></table><h3 id="randomization" tabindex="-1">Randomization, constraints, and <code>randsequence</code> <a class="header-anchor" href="#randomization" aria-label="Permalink to &quot;Randomization, constraints, and `randsequence` {#randomization}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Scope <code>randomize()</code> / <code>std::randomize()</code> (18.12)</strong></td><td>Unconstrained whole packed variables (any width, signed/unsigned, packed structs) and scalar enums up to 64 bits (known declared values); <code>with</code> constraints on integral variables ≤ 64 bits</td><td><code>with</code> constraints on non-integral or &gt; 64-bit variables (such as enums); enums with unresolved/X/Z values; unpacked arrays, nets, constants, selects, and concatenation arguments</td></tr><tr><td><strong>Class <code>randomize()</code> and <code>randc</code> (18.3–18.4, 18.8, 18.11)</strong></td><td>2-state and 4-state integral <code>rand</code> properties (any width unconstrained; 4-state <code>rand</code> takes 2-state values), scalar enums (declared values), fixed-size and dynamic random arrays of 2-state integrals (a constraint may name the size of an array of elements &gt; 64 bits, not its elements), inherited properties, <code>pre_randomize</code>/<code>post_randomize</code>, <code>rand_mode()</code>, <code>srandom()</code>, <code>get_randstate()</code>/<code>set_randstate()</code>, explicit member lists, <code>randomize(null)</code>; unconstrained <code>randc</code> on 1–16-bit 2-state integers and scalar enums up to 65,536 members</td><td>Aggregate properties (static or non-static); <code>randc</code> static properties or <code>randc</code> arrays; random arrays of elements other than 2-state integrals; constraints on elements &gt; 64 bits of random arrays; random object or <code>string</code> properties; <code>randc</code> domains &gt; 16 bits or &gt; 65,536 enum members; enums with unresolved/X/Z values</td></tr><tr><td><strong>Constraint blocks and expressions (18.5)</strong></td><td>1–64-bit scalar integer properties (constant bit/part-selects of any declared range), comparisons, logical/bitwise ops, <code>+</code>, <code>-</code>, <code>*</code>, <code>**</code> (Table 11-4; <code>0 ** -1</code> is X in 4-state simulation and 0 in 2-state); shifts; <code>if</code>/<code>else</code> and <code>-&gt;</code> (state guards evaluated before solving); <code>inside</code> (scalar values, inclusive ranges, and array properties of integral elements, which stand for their elements); <code>foreach</code>, <code>sum()</code>, and constant-index elements on random arrays (array sizes solved before elements/function calls; past-the-end reads 0); array elements at positions that state expressions give (<code>a[i + 1]</code>, <code>b[i]</code> in a loop over <code>a</code>; X/Z positions read 0); <code>dist</code> (constant weights/range bounds, <code>$</code> type bounds); <code>unique</code> on singular class properties of equivalent types; <code>soft</code> constraints and <code>disable soft</code>; <code>solve ... before</code>; <code>constraint_mode()</code>, inheritance, overrides; <code>==</code>/<code>!=</code> on class handles; single-hop handle members (<code>h.m</code>, <code>this.h.m</code>, <code>super.h.m</code>, <code>item.h.m</code>, static handles, selects <code>h.m[3:0]</code>/<code>hs[i].m[0]</code>); class functions with input arguments (18.5.11); the bit-vector functions <code>$countones</code>, <code>$onehot</code>, <code>$onehot0</code>, <code>$isunknown</code>, and <code>$countbits</code> with constant control bits (20.9), also in <code>foreach</code></td><td>Constrained enums or <code>randc</code>; 4-state static properties read as state, 4-state members of other objects, or 4-state array elements in constraints; constraints naming static properties in a <code>rand</code>-handle-reached object; <code>sum() with</code>; <code>soft</code> inside <code>foreach</code>; array positions that a random variable decides; <code>/</code> and <code>%</code>; <code>dist</code> with <code>default :/</code>, non-constant weights, or <code>:/</code> ranges with non-constant bounds; <code>unique</code> on other variables, arrays, or slices; deeper handle chains (<code>h.g.m</code>); <code>$countbits</code> control bits that are not constants or that count <code>&#39;x</code> without <code>&#39;z</code> (or <code>&#39;z</code> without <code>&#39;x</code>); class function calls in constraint loops, inline constraints, <code>rand</code>-handle-reached objects, or arguments of another constraint call; typed parameters in constraints; associative arrays, arrays of the caller, nested arrays, X/Z wildcard items, or <code>$</code> bounds in <code>inside</code> sets</td></tr><tr><td><strong>Inline <code>randomize() with { ... }</code> (18.7)</strong></td><td>Same constraint subset; unqualified receiver properties, receiver handle variable (<code>h.randomize() with { h.x &gt; 0; }</code>, read once at call start), caller-scope scalar inputs and expressions computed from caller variables and non-random receiver properties (<code>buffer[i]</code>, <code>req.rw</code>, <code>memory[rsp.addr]</code>, <code>m.get_size()</code>), and <code>local::</code> for non-property caller locals/arguments</td><td>Aggregate caller-scope inputs; typed parameter inputs; <code>local::</code> naming a property of the caller&#39;s class; caller expressions computed from a random variable (<code>memory[h.addr]</code> with <code>rand addr</code>); unqualified receiver <code>static</code> properties (rejected rather than falling back to a caller variable of the same name)</td></tr><tr><td><strong><code>randsequence</code> (18.17)</strong></td><td>Non-recursive productions with weights, <code>rand join</code> (with bias; see <a href="#random-numbers">Random numbers</a>), and <code>input</code> formals/return values of packed/scalar types</td><td>Recursive productions; code blocks after a weight; non-<code>input</code> formals; formals or values of unpacked, dynamically sized, or <code>event</code> types</td></tr></tbody></table><p>See <a href="#random-numbers">Random numbers</a> for the solver policy, <code>soft</code>, <code>dist</code>, <code>solve before</code>, 4-state constraint semantics, constraint function calls, and the <code>rand join</code> bias formula.</p><h3 id="dynamic-containers" tabindex="-1">Dynamic containers <a class="header-anchor" href="#dynamic-containers" aria-label="Permalink to &quot;Dynamic containers {#dynamic-containers}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Container and nesting shapes</strong></td><td>Dynamic arrays (<code>T a[]</code>), queues (<code>T q[$]</code>, bounded <code>T q[$:N]</code>), associative arrays (<code>T m[K]</code>), nested dynamic containers (<code>int m[string][$]</code>, <code>T m[C][C][E]</code>), and dynamic containers of one-dimensional fixed-size unpacked arrays (<code>int a[][2]</code>, <code>bit [63:0] m[int][1]</code>: an element that takes its default, as a missing associative entry or one <code>new[]</code> adds, is an array of default elements, 7.4, 7.8.6) as module variables, locals, and class properties</td><td>Fixed-size unpacked arrays of dynamic containers (<code>int a[2][$]</code>, including via <code>typedef</code>); dynamic containers of multidimensional fixed-size unpacked arrays (<code>int a[][2][3]</code>) or of fixed-size arrays of unpacked arrays; container ports; <code>const</code> containers</td></tr><tr><td><strong>Element types</strong></td><td>Packed integrals of any width, <code>string</code>, class handles, <code>chandle</code>, supported unpacked structs (no fixed-size array or defaulted members), and nested dynamic containers</td><td><code>real</code> / <code>shortreal</code> elements; named <code>event</code> elements</td></tr><tr><td><strong>Associative array keys</strong></td><td>Integral types of any width (including packed structs and enums), <code>string</code>, class handles, and <code>process</code> handles</td><td>Wildcard <code>[*]</code>; <code>real</code>, unpacked types, or other non-integral/non-handle key types</td></tr><tr><td><strong>Literals, <code>new[]</code>, and assignments</strong></td><td>Positional patterns, <code>{}</code> / element concatenations, <code>new[n]</code> with another compatible dynamic array/queue or an assignment pattern (including <code>&#39;{default: v}</code> for scalar/non-container/non-struct elements), default-only associative literals (<code>&#39;{default: v}</code>, 7.8.6), and blocking element or bit/part-select writes (integral ≤ 64 bits, side-effect-free container/index)</td><td><code>new[n](fixed_array)</code>; <code>new[]</code> assignment pattern mixing <code>default:</code> with other keys or for container/unpacked-struct elements; explicit index entries or mixed index/<code>default:</code> associative literals; slices; keyed patterns; associative arrays inside concatenations; nonblocking element assignments; compound element assignments whose container or index has side effects or whose element is a <code>string</code>, handle, or container; writing a member of an unpacked-struct element directly (assign the whole element)</td></tr><tr><td><strong>Ordering and comparison (7.12.2)</strong></td><td><code>reverse</code> and <code>shuffle</code> (dynamic arrays, queues, and 1D fixed-size arrays of ≤ 64-bit non-struct elements); <code>sort</code> and <code>rsort</code> (integral ≤ 64 bits and <code>string</code> without <code>with</code>; unpacked structs, class handles, and elements &gt; 64 bits with a <code>with</code> expression on dynamic arrays/queues); <code>==</code>/<code>!=</code>/<code>===</code>/<code>!==</code> on containers, also of elements &gt; 64 bits and of unpacked structs (an X or Z bit makes <code>==</code> <code>x</code> unless a known bit differs, 11.4.5)</td><td><code>sort</code>/<code>rsort</code> without <code>with</code> on elements &gt; 64 bits, unpacked structs, or class handles; ordering fixed-size arrays that are multidimensional, of unpacked structures, of elements &gt; 64 bits, or with a <code>with</code> expression; comparison of containers of unpacked structs with dynamic-array, queue, or associative-array members; <code>==</code>/<code>!=</code> on containers of unpacked structs that mix 2-state and 4-state members or have 4-state members wider than 64 bits in all</td></tr><tr><td><strong>Reduction methods (7.12.3)</strong></td><td><code>sum</code>, <code>product</code>, <code>and</code>, <code>or</code>, <code>xor</code> on 1D array variables or dynamic-container class properties (fixed arrays may be &gt; 64 bits; dynamic containers ≤ 64 bits)</td><td><code>with</code> expressions and iterator arguments; multidimensional arrays; dynamic containers with elements &gt; 64 bits</td></tr><tr><td><strong>Locator methods (7.12.1)</strong></td><td><code>find</code>, <code>find_index</code>, <code>find_first</code>, <code>find_first_index</code>, <code>find_last</code>, <code>find_last_index</code> (with <code>with</code>), and <code>min</code>, <code>max</code>, <code>unique</code>, <code>unique_index</code> (with or without <code>with</code>, integral ≤ 64 bits or <code>string</code>) on dynamic arrays, queues, associative arrays, and 1D fixed arrays; <code>item</code> / named iterator and <code>.index</code></td><td>Index-returning locators on associative arrays with integral keys &gt; 64 bits; locator methods in continuous assignments, on multidimensional fixed arrays, on <code>real</code> elements, or as discarded statements; <code>with</code> / iterator clauses outside this locator subset</td></tr><tr><td><strong>Queries and subroutine formals</strong></td><td>Outer <code>$size</code>, sequence <code>$left</code>/<code>$right</code>/<code>$low</code>/<code>$high</code>/<code>$increment</code>, <code>$dimensions</code>; <code>$bits(q.pop_front)</code> on integral queues; <code>input</code>/<code>output</code>/<code>inout</code> container formals with compatible container variable actuals of matching element type and queue bound</td><td>Type queries (<code>$bits</code>, …) on <code>string</code>- or class-valued queue pop results; element-dimension queries and associative bound queries; function return values of container type; class properties or container elements as <code>output</code>/<code>inout</code> actuals; actuals whose element type differs from the formal&#39;s</td></tr></tbody></table><h3 id="strings" tabindex="-1">Strings <a class="header-anchor" href="#strings" aria-label="Permalink to &quot;Strings {#strings}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Scalar <code>string</code> variables and methods</strong></td><td>Standard <code>string</code> operations and methods (except <code>atoreal</code>/<code>realtoa</code>), hierarchical names (including generate blocks), <code>inside</code> / <code>case inside</code> equality matching on strings, <code>$display</code>/<code>$sformatf</code>, DPI-C <code>string</code> arguments/results, <code>$value$plusargs</code> <code>%s</code> into a <code>string</code> destination, and file I/O (<code>$fopen</code>, <code>$fdisplay</code>/<code>$fwrite</code>, <code>$writememh</code>/<code>$writememb</code>, <code>$fgets</code>, <code>$ferror</code>, <code>$sscanf</code>/<code>$fscanf</code> source/format)</td><td><code>atoreal</code> / <code>realtoa</code>; value range items (<code>[&quot;a&quot;:&quot;z&quot;]</code>) in <code>inside</code> / <code>case inside</code> on strings; <code>string</code> variable as the format argument of <code>$value$plusargs</code> (or non-<code>%s</code> conversion into a <code>string</code> destination); <code>string</code> values in VPI, VCD/FST output, and the TypeScript API</td></tr><tr><td><strong>Fixed unpacked arrays of <code>string</code></strong></td><td>Assignment patterns, whole-array and subarray copies, indexed reads/writes, non-mutating element methods, and blocking character writes plus <code>putc</code>/<code>itoa</code>/<code>hextoa</code>/<code>octtoa</code>/<code>bintoa</code> on complete elements</td><td>Nonblocking character writes; method calls on whole arrays or subarrays; array-valued <code>string</code> subroutine arguments or return values</td></tr></tbody></table><h3 id="reference-arguments" tabindex="-1">Reference arguments <a class="header-anchor" href="#reference-arguments" aria-label="Permalink to &quot;Reference arguments {#reference-arguments}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Qualifiers (13.5.2)</strong></td><td><code>ref</code> and <code>const ref</code> on automatic subroutines and class methods (including virtual methods)</td><td><code>ref static</code></td></tr><tr><td><strong>Actual arguments</strong></td><td>Variables (scalars, vectors, <code>string</code>, class handles, dynamic containers, unpacked arrays, unpacked structs), class properties, fixed-size unpacked array elements, and unpacked struct members</td><td>Elements of dynamic arrays, queues, or associative arrays; elements of class properties</td></tr><tr><td><strong>Operations on <code>ref</code> formals</strong></td><td>Whole reads/writes, forwarding a property-bound <code>ref</code> to an <code>output</code>/<code>inout</code> argument, and selects on array-element <code>ref</code>s at compile-time or unrolled-loop indices</td><td>Partial (bit/part-select) writes to a formal bound to a class property or its member; selects on a formal bound to an array element at a run-time-only position</td></tr></tbody></table><h3 id="sampled-values" tabindex="-1">Deferred assertions, assertion controls, and sampled values <a class="header-anchor" href="#sampled-values" aria-label="Permalink to &quot;Deferred assertions, assertion controls, and sampled values {#sampled-values}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Deferred immediate assertions (<code>assert #0</code>, <code>assert final</code>, …)</strong></td><td>Module items and procedural deferred assertions whose action is a single display or severity task call</td><td>User subroutines or more than one statement in the action block</td></tr><tr><td><strong>Assertion control tasks (20.11)</strong></td><td>Zero-argument <code>$asserton</code> and <code>$assertoff</code> (stopping and restarting all assertions in module/design scopes)</td><td><code>$assertkill</code>, <code>$assertcontrol</code>, action control tasks (<code>$assertpasson</code>, …), and level/scope/assertion arguments; calling <code>$asserton</code>/<code>$assertoff</code> in a package or <code>$unit</code> (assertions in package subroutines/classes are not controlled); calling them from <code>always_comb</code>/<code>always_latch</code> when any procedure other than <code>initial</code> or an edge-controlled one also calls them; combining them with multi-path concurrent sequences (<code>##[m:n]</code> or <code>or</code>)</td></tr><tr><td><strong>Sampled value functions (16.9.3)</strong></td><td><code>$sampled</code> in processes, combinational logic, multiclocked sequences, and callees; <code>$past</code>, <code>$rose</code>, <code>$fell</code>, <code>$stable</code>, and <code>$changed</code> in edge-triggered processes (and callees) with an inferred clock</td><td>Explicit clocking event argument; use without a clock to infer; nested calls (<code>$past($past(a))</code>); operands reading an unpacked array; <code>$past</code>/<code>$rose</code>/<code>$fell</code>/<code>$stable</code>/<code>$changed</code> inside multiclocked sequences or with function-call operands in concurrent assertions</td></tr></tbody></table><h3 id="concurrent-assertions" tabindex="-1">Concurrent assertions <a class="header-anchor" href="#concurrent-assertions" aria-label="Permalink to &quot;Concurrent assertions {#concurrent-assertions}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Directives and placement</strong></td><td>Module and generate <code>assert property</code>, <code>assume property</code>, and <code>cover property</code> with an explicit clock; procedural <code>expect (property_spec) action_block</code> (16.17) in processes and tasks with an explicit clock</td><td>Procedural concurrent assertions (<code>assert</code>/<code>assume</code>/<code>cover property</code> inside procedures); implicit or default clocking</td></tr><tr><td><strong>Single-clock sequences and properties</strong></td><td>Boolean properties; <code>p iff q</code> of two Boolean expressions (also as consequent of <code>|-&gt;</code>, where <code>a |-&gt; b iff c</code> is <code>a |-&gt; (b iff c)</code>); fixed-delay sequences (<code>a ##1 b</code>, up to 1024 ticks) joined by <code>|-&gt;</code> or <code>|=&gt;</code>; bounded cycle-delay ranges (<code>a ##[1:3] b</code>, including leading), <code>or</code>, <code>and</code>, <code>intersect</code>, and <code>b throughout s</code> (up to 1024 ways to match, as whole property or consequent of a single-path antecedent, without match items); <code>disable iff</code> on single- or multi-cycle sequences (16.12); local variables of built-in integral types and match items (in fixed-delay module/generate assertions)</td><td>Unbounded cycle-delay ranges (<code>##[1:$]</code>); repetition; sequence operator <code>within</code>; <code>intersect</code> of sequences that never match on one tick; multi-path sequences in an implication antecedent, in <code>expect</code>, or with local variables/match items; <code>disable iff</code> in <code>expect</code> or multiclocked sequences; <code>iff</code> with multi-cycle or named operands or chained <code>a iff b iff c</code></td></tr><tr><td><strong>Until properties (16.12.12)</strong></td><td><code>a until b</code>, <code>a s_until b</code>, <code>a until_with b</code>, and <code>a s_until_with b</code> of Boolean operands, as the whole property or as the consequent of <code>|-&gt;</code> or <code>|=&gt;</code> with a Boolean antecedent, with <code>disable iff</code>, also as the body of a named property; attempts of a strong form still pending when the simulation ends fail then, those of a weak form neither pass nor fail (F.5.3.1)</td><td>Operands other than Boolean expressions (sequences, properties, instances of named sequences); an until property as an operand of another property operator (<code>(a until b) until c</code>, <code>iff</code>); until properties in <code>expect</code>; until properties in a design that calls an assertion control task (20.11)</td></tr><tr><td><strong>Multiclocked sequences (16.13)</strong></td><td>Whole-property sequences joining single-path singly clocked subsequences via <code>##1</code> or <code>##0</code> across clock changes (value event controls incl. 4-state edges, <code>iff</code>, static virtual interface members; parenthesized clocking groups up to 64 nested groups, 16.13.3); <code>$sampled</code> inside subsequences</td><td>Multiclocked sequences inside implications, with <code>disable iff</code>, or with local variables/match items; named events as clocks; operators other than <code>##1</code>/<code>##0</code> across clock changes; <code>$past</code>/<code>$rose</code>/<code>$fell</code>/<code>$stable</code>/<code>$changed</code> in any subsequence; nesting beyond 64 groups</td></tr><tr><td><strong>Named properties and sequences</strong></td><td>Parameterless declarations in the same module outside generate blocks, whose body stays within this subset; a named sequence without local variables may be an operand of another sequence (same clock or leading)</td><td>Formal arguments; declarations in other scopes or generate blocks; instances of named sequences clocked differently or with local variables inside a multi-cycle sequence</td></tr><tr><td><strong>Function calls in assertions (16.6)</strong></td><td>Pure (side-effect-free) function calls in operands, <code>disable iff</code> conditions, and match-item values (arguments receive sampled values; body reads current values, 16.5.1)</td><td>Impure function calls (functions with <code>output</code>/<code>inout</code>/<code>ref</code>/<code>const ref</code> formals, non-local writes, retained static state, side-effecting system calls, or string/class method calls directly or transitively); DPI import calls; function calls in operands of <code>$past</code>/<code>$rose</code>/<code>$fell</code>/<code>$stable</code>/<code>$changed</code></td></tr><tr><td><strong>Action blocks</strong></td><td>Untimed blocking statements, report/severity tasks, and subroutine calls that do not suspend, perform nonblocking assignments, start or control processes, or trigger events</td><td>Timed or nonblocking action statements; suspending, event-triggering, or process-controlling calls</td></tr></tbody></table><p>For <code>expect (property_spec) action_block</code> (16.17), the executing process makes one attempt starting from the next clocking event, decides each step on sampled values, runs the pass or fail statement (by default <code>$error</code>) in the Reactive region, and continues. Multi-path sequences pass at the first tick any path matches and fail at the first tick no path can still match; a missed antecedent succeeds vacuously at that tick.</p><h3 id="covergroups" tabindex="-1">Coverage groups <a class="header-anchor" href="#covergroups" aria-label="Permalink to &quot;Coverage groups {#covergroups}&quot;">​</a></h3><p>A covergroup (clause 19) is a type: declared in a module, a program, a package, the compilation unit or a generate block, or embedded in a class (19.4). <code>new</code> constructs an instance, with the arguments of the covergroup; <code>sample()</code> samples it, with the arguments of a <code>with function sample</code> declaration, and so does each occurrence of the clocking event of the covergroup (<code>covergroup cg @(posedge clk);</code>) for each of its instances (19.3); <code>get_inst_coverage()</code>, <code>get_coverage()</code>, <code>T::get_coverage()</code> and <code>$get_coverage()</code> give coverage, also of a coverpoint or cross (<code>c.cp.get_inst_coverage()</code>, <code>T::cp::get_coverage()</code>) and with the covered bins and the bins in two <code>int</code> variables (<code>c.get_coverage(covered, total)</code>); <code>start()</code>, <code>stop()</code> and <code>set_inst_name()</code> control an instance (19.8). The results are read through <code>Simulation::coverage()</code> (see <a href="#coverage">Coverage</a>).</p><p>A coverpoint (19.5) is of an integral type of any width: with or without a label, with a type of its own, and with an <code>iff</code> guard, whose expression is evaluated first. Its expression and its guard read the arguments of the covergroup and of <code>sample</code>, then the members of the class of an embedded covergroup, then the names of the scope. Its bins are the automatic bins of 19.5.3, also those of an enumeration, or the bins it declares for values (19.5.1 to 19.5.6): one bin, a bin for each value (<code>bins b[]</code>) or a number of bins (<code>bins b[N]</code>) of a list of values and ranges, also ranges with a tolerance (<code>[a +/- b]</code>, <code>[a +%- b]</code>), of the values a <code>with</code> expression keeps, or of the elements of an array; <code>default</code> bins; <code>ignore_bins</code> and <code>illegal_bins</code>; <code>wildcard</code> bins; and a guard on any of them (<code>iff</code>). A bin value is a constant, an argument of the covergroup or a call of a function with these, which the construction evaluates, so the instances of one type may differ in their bins. A sample of an illegal value is reported as an error.</p><p>A cross (19.6) crosses two or more coverpoints of the covergroup, or variables, which get a coverpoint of their own: an integral variable or net, a property of the class of an embedded covergroup, or an argument of the covergroup or of <code>sample</code>. It has a bin for each combination of bins of its coverpoints that take part in their coverage, and its <code>bins</code>, <code>ignore_bins</code> and <code>illegal_bins</code> take the combinations their select expressions select: <code>binsof(cp)</code> and <code>binsof(cp.bin)</code>, with <code>intersect {...}</code>, <code>!</code>, <code>&amp;&amp;</code>, <code>||</code>, parentheses, and the identifier of the cross itself, which selects every combination. A cross and each of its bins may have a guard (<code>iff</code>). A sample of an illegal combination is reported as an error.</p><p>The definition may assign every member of <code>option</code>, each at the levels 19.10 gives it, with any expression of the scope of <code>new</code> as the value, and the members of <code>type_option</code> but <code>real_interval</code>, with a constant (19.7.1). A procedure reads and writes the members of <code>option</code> of an instance and of its items (<code>c.option.weight = 2;</code>, <code>c.cp.option.at_least = 3;</code>) and of <code>type_option</code> of the type and of its items, through the type or through an instance (<code>T::type_option.comment = &quot;x&quot;;</code>, <code>T::cp::type_option.weight = 3;</code>, <code>c.type_option.merge_instances = 1;</code>), but for the members the standard lets only the definition set (19.7, 19.7.1).</p><p>A construct of the <strong>Not supported</strong> column is rejected where a <code>new</code> or a method of the covergroup is written, not where the covergroup is declared: a covergroup that nothing constructs is accepted whatever it declares, and so is a variable of its type. The exceptions are <code>!</code> before a parenthesized selection and a conditional cross set expression, which the parser rejects where the covergroup is declared. All of them point to <a href="https://github.com/celox-sim/celox/issues/4294" target="_blank" rel="noreferrer">#4294</a>, which tracks what is left of clause 19.</p><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Declarations (19.3, 19.4)</strong></td><td>A covergroup of a module, a program, a package, the compilation unit or a generate block; a covergroup embedded in a class; variables of a covergroup type</td><td><code>covergroup extends</code> (19.4.1); a covergroup declared in an interface, which is rejected with the interface in most positions, and always when it has a clocking event; one declared in a checker or in a loop generate block; constructing or sampling a covergroup type that a module takes as a type parameter (it declares variables there)</td></tr><tr><td><strong>Coverpoints (19.5)</strong></td><td>Coverpoints of an integral type of any width, with or without a label, with a type of their own, and with an <code>iff</code> guard</td><td>A coverpoint of a <code>real</code> type; one of an enumeration whose enumerators have x or z bits; a coverpoint of a clockvar of a clocking block</td></tr><tr><td><strong>Bins (19.5)</strong></td><td>The automatic bins of 19.5.3, also those of an enumeration; bins of values and ranges (<code>bins b = {0, [1:3], [8:$]};</code>) whose values are constants, arguments of the covergroup or calls of functions with these; bin arrays (<code>bins b[]</code>, <code>bins b[N]</code>); ranges with a tolerance (<code>[a +/- b]</code>, <code>[a +%- b]</code>) of integral operands; <code>default</code> and <code>default[]</code> bins; <code>ignore_bins</code> and <code>illegal_bins</code>; <code>wildcard</code> bins; a guard on a bin (<code>bins b = {1} iff (en);</code>); <code>with</code> filters (<code>bins b[] = {[0:255]} with (item % 3 == 0);</code>, <code>bins b = cp with (f(item));</code>); bins of a set expression (<code>bins b[] = S;</code>) that is an array parameter with integral elements, or a dynamic array, a queue or a constant array of the class of an embedded covergroup with integral elements of at most 64 bits</td><td>Transition bins and <code>default sequence</code> bins (19.5.2); <code>bins b[N] = default</code> (the standard does not say how the values are distributed); a <code>with</code> filter on a bin array, on <code>ignore_bins</code> or on <code>illegal_bins</code> whose values are constants and more than 1,048,576, such as <code>ignore_bins b = cp with (...)</code> on an <code>int</code> coverpoint (on one <code>bins</code> bin such a filter is supported, see <a href="#coverage">Coverage</a>); a wildcard value of more than 65,536 ranges of values in a bin array or under such a filter; a set expression of any other form: an assignment pattern, a concatenation, a fixed-size array that is no parameter, an array of strings, handles or elements of more than 64 bits; a tolerance range with a <code>real</code> operand; a bin value that is not integral</td></tr><tr><td><strong>Crosses (19.6)</strong></td><td>Crosses of coverpoints and of integral variables or nets (a variable gets a coverpoint of its own), with or without a label, with an <code>iff</code> guard; <code>bins</code>, <code>ignore_bins</code> and <code>illegal_bins</code> of select expressions of <code>binsof(cp)</code> and <code>binsof(cp.bin)</code>, with <code>intersect {...}</code> lists whose values are constants, arguments of the covergroup or calls of functions with these, <code>!</code>, <code>&amp;&amp;</code>, <code>||</code>, parentheses and the identifier of the cross (<code>bins all = X;</code>); a guard on a cross bin</td><td><code>with</code> and <code>matches</code> in a select expression (19.6.1.2); cross set expressions and functions declared in a cross body (19.6.1.3, 19.6.1.4); <code>!</code> before a parenthesized selection (<code>!(binsof(a) &amp;&amp; binsof(b))</code>) and a conditional cross set expression, both rejected where the covergroup is declared; a cross that lists one item twice; <code>binsof</code> of a coverpoint that the cross does not cross; <code>&amp;&amp;</code> and <code>||</code> that alternate through more than 32 levels of parentheses; an <code>intersect</code> list that meets values only a sample sorts into bins (see <a href="#coverage">Coverage</a>)</td></tr><tr><td><strong>Options (19.7, 19.7.1)</strong></td><td>Every member of <code>option</code> in the definition, at the levels 19.10 gives it; the members of <code>type_option</code> in the definition with a constant value: <code>weight</code>, <code>goal</code>, <code>comment</code> (a string literal), <code>merge_instances</code>, <code>distribute_first</code>, and <code>strobe</code>, which has no effect on a covergroup without a clocking event (19.3); in a procedure, the members of <code>option</code> of an instance and of its items, and of <code>type_option</code> of the type and of its items, through <code>::</code> or through an instance, read and assigned with <code>=</code></td><td><code>type_option.real_interval</code> (real coverpoints are not supported); <code>type_option.strobe</code> read in a procedure; a <code>type_option.comment</code> that is no string literal, such as a string parameter; a member assigned with another operator (<code>+=</code>, <code>++</code>) or with <code>&lt;=</code>; a member read in the select of a place that an increment or a compound assignment writes (<code>arr[c.cp.option.weight]++</code>); <code>option</code> or <code>type_option</code> used as a whole structure; <code>type_option.strobe = 1</code> of a covergroup with a clocking event (<code>covergroup strobe sampling</code>), as no sample is taken in the Postponed region</td></tr><tr><td><strong>Sampling (19.3, 19.8.1)</strong></td><td><code>sample()</code>; the clocking event of a covergroup (<code>covergroup cg @(posedge clk);</code>) for each instance: one that a declaration of a module or a program constructs with <code>new</code> as its initializer (<code>cg c = new;</code>, also in a generate block, a loop&#39;s included), and one that any other <code>new</code> constructs, in a procedure, a task, a function, the <code>new</code> method of the class of an embedded covergroup (19.4) or another declaration initializer of a module or a program (<code>C obj = new;</code>, <code>cg a[2] = &#39;{new, new};</code>, a static property of a class). The event is any event control on signals, with edges, changes, <code>or</code> and comma lists and <code>iff</code> (9.4.2), on named events (also of an object: <code>@ev</code>, <code>@(this.ev)</code>, and <code>@(obj.ev)</code> where <code>ev</code> is a named event of the object a handle property <code>obj</code> holds), on properties of the class of an embedded covergroup (<code>@m_z</code>, <code>@(posedge clk_bit)</code>), on hierarchical names and on members of the interface instance a virtual interface variable or property denotes (<code>@(posedge vif.clk)</code>). It is bound where the covergroup is declared: in its scope, also a package or the compilation unit, or in the class of an embedded one. The instances of a covergroup of a module or a program, whatever constructs them, are sampled by the samplers of the type: at one <code>posedge</code> or <code>negedge</code> of a one-bit variable, with or without <code>iff</code>, with the flip-flops of the edge, before their nonblocking assignments; at every other event, and in a program, by processes that wait for it. An instance of an embedded covergroup, or of a covergroup of a package or the compilation unit, is sampled by a process its construction starts: see <a href="#deviations-standard-code">Clocking events of covergroups</a> for how each differs from 19.3</td><td>An instance with a clocking event that a declaration of a package or the compilation unit constructs, itself or through a subroutine or a class constructor it calls (<code>covergroup sampling event of an instance that a declaration of a package or the compilation unit constructs</code>); an instance of a covergroup embedded in a class, or of a covergroup of a package or the compilation unit, constructed in an <code>always_comb</code>, <code>always_latch</code> or <code>always_ff</code> procedure, a continuous assignment or a final procedure, itself or through a subroutine or constructor (<code>covergroup sampling event of an instance constructed in an always_comb procedure</code>, <code>… in an always_latch procedure</code>, <code>… in a continuous assignment</code>, <code>… in an always_ff procedure</code>, <code>… in a final procedure</code>), which would start a process there (an instance of a covergroup of a module or a program may be constructed in each); an event of an embedded covergroup on a value member of an object that a handle property holds, such as 19.4&#39;s <code>@(m_obj.m_ev)</code> with an <code>int m_ev</code>, also in <code>iff</code> (<code>covergroup sampling event on a member of an object that a handle property holds</code>), as no event control of a process supports one; every use of a covergroup with a clocking event that is declared in an interface, <code>sample()</code>, <code>get_coverage()</code> and the options included; a clocking event that names an argument of the covergroup (19.3: &quot;A clocking event may refer to arguments of the covergroup&quot;); clocking events under <code>Simulator</code> (see <a href="#celox-execution-model">Celox execution model</a>); a block event (<code>@@(begin f)</code>); <code>sample()</code> in a sequence match item</td></tr><tr><td><strong>Arguments (19.3, 19.8.1)</strong></td><td>The arguments of a covergroup and of its <code>with function sample</code> declaration; <code>ref</code> and <code>const ref</code> arguments of a covergroup whose instances declarations of a module or a program construct with <code>new</code> as their initializers (<code>cg c = new(bus_a);</code>, also in a generate block), which read the variables their actuals name at each sample (see <a href="#coverage">Coverage</a>); <code>ref</code> arguments of the sample method, which each call passes</td><td>A <code>ref</code> argument of a covergroup that any other <code>new</code> constructs: in a procedure, a subroutine, a class or another declaration initializer, one embedded in a class, and one of a covergroup of a package or the compilation unit (<code>covergroup ref argument outside a declaration with an initializer</code>); <code>sample()</code> of an instance with <code>ref</code> arguments through anything but the variable of its declaration, such as another variable that holds the handle, an element of an array or a local of the same name (<code>covergroup ref argument of an instance sampled through a variable other than its declaration</code>); any write of that variable but its initializer, also as the actual of an <code>output</code>, <code>inout</code> or <code>ref</code> argument (<code>covergroup ref argument of an instance whose variable … is written outside its declaration</code>); a <code>ref</code> actual that is a hierarchical name, a member of a structure that is no unpacked structure variable, a class property that is not static, an element at an index that is not constant, or an element of a dynamic array, a queue or an associative array; a <code>ref</code> argument left to its default; a <code>ref</code> argument of the covergroup of a type that is neither integral nor a fixed-size array of an integral type, such as a string, a class handle, a queue or an unpacked structure; input arguments of unpacked type; an input argument of the covergroup that a coverpoint reads and that is not of an integral type, a string or a class handle, such as a <code>real</code></td></tr><tr><td><strong><code>let</code> declarations (11.12)</strong></td><td>—</td><td>A <code>let</code> is not expanded in what follows the name of a covergroup: a covergroup whose argument types or defaults, coverpoint expressions, crossed variables, guards, bin values, <code>intersect</code> values, <code>with</code> expressions or option values name one is rejected, unless an argument of the covergroup or of <code>sample</code> has the name (<code>item</code> in a <code>with</code> expression is the value of the bin, whatever is named so)</td></tr><tr><td><strong>Methods (19.8)</strong></td><td><code>sample()</code>, <code>get_inst_coverage()</code>, <code>get_coverage()</code>, <code>T::get_coverage()</code>, and <code>$get_coverage()</code>; <code>get_coverage</code> and <code>get_inst_coverage</code> with two <code>ref int</code> arguments; <code>start()</code>, <code>stop()</code> and <code>set_inst_name()</code>; the methods Table 19-5 gives coverpoints and crosses (<code>c.cp.get_inst_coverage()</code>, <code>c.x.stop()</code>, <code>T::cp::get_coverage()</code>); a method of an embedded covergroup called on its variable (<code>cg</code> in the class, <code>obj.cg</code>)</td><td>A method of an embedded covergroup called on another expression that gives the handle, such as a conditional expression</td></tr><tr><td><strong>Construction (19.3, 19.4)</strong></td><td><code>new</code> with the arguments of the covergroup; in the <code>new</code> method of its class, an embedded covergroup assigned as <code>cg = new;</code> or <code>this.cg = new;</code></td><td><code>new</code> with a covergroup handle as a shallow copy (8.12); an embedded covergroup assigned through another handle of the class (<code>other.cg = new;</code>) in the <code>new</code> method (outside that method the assignment is the error 19.4 makes it)</td></tr><tr><td><strong>Type names (20.6.1)</strong></td><td>—</td><td><code>$typename</code> of a covergroup type, of a variable of one, or of an array or structure that holds one (20.6.1 has no rule for the name)</td></tr><tr><td><strong>Results (19.9)</strong></td><td><code>Simulation::coverage()</code> and <code>Simulator::coverage()</code> (see <a href="#coverage">Coverage</a>)</td><td>The coverage database; see <a href="#deviations-standard-code">No coverage database</a></td></tr></tbody></table><h3 id="formatted-output-to-strings" tabindex="-1">I/O, formatting, and system tasks <a class="header-anchor" href="#formatted-output-to-strings" aria-label="Permalink to &quot;I/O, formatting, and system tasks {#formatted-output-to-strings}&quot;">​</a></h3><p>Runtime I/O (<code>$fopen</code>, file <code>$display</code>/<code>$write</code>, <code>$system</code>, plusargs, <code>$sformatf</code> family, etc.) requires a timed <code>Simulation</code> process — calls from combinational processes and continuous assignments are rejected. <code>$system</code> is unsupported on WebAssembly hosts. For <code>$readmemh</code> and <code>$readmemb</code>, see <a href="#memory-files">Memory files</a>.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong><code>$strobe</code> / <code>$fstrobe</code> (21.2.2, 21.3.2)</strong></td><td>Module/static expressions in scheduled processes (including <code>b</code>/<code>o</code>/<code>h</code> forms)</td><td>Calls in subroutines; procedural locals, unrolled loop variables, updates, or effectful calls in arguments</td></tr><tr><td><strong><code>$monitor</code> / <code>$fmonitor</code> (21.2.3, 21.3.2)</strong></td><td>Whole static scalar variables, console <code>string</code> variables (<code>$monitor</code>), constants, and direct time queries in scheduled processes</td><td>Array elements, slices, general expressions, <code>string</code> variables in <code>$fmonitor</code>, and the <code>$strobe</code> call-context restrictions above</td></tr><tr><td><strong><code>$fopen</code>, <code>$fdisplay</code>/<code>$fwrite</code>, <code>$writememh</code>/<code>$writememb</code></strong></td><td>UTF-8 string literals, packed integral strings, and <code>string</code> variables for paths, modes, and formatted arguments; <code>$writememh</code>/<code>$writememb</code> on static unpacked arrays</td><td>Non-UTF-8 file names or modes; <code>$writememh</code>/<code>$writememb</code> on dynamic or associative arrays</td></tr><tr><td><strong><code>$fgets</code> (21.3.4.2)</strong></td><td>Writable <code>string</code> variable or selected fixed string-array element destinations</td><td>Packed integral buffers, class properties, or dynamic containers as destinations</td></tr><tr><td><strong><code>$ferror</code> (21.3.7)</strong></td><td><code>string</code> variable, selected fixed string-array element, or packed buffer ≥ 640 bits</td><td>Class properties or dynamic containers as destinations</td></tr><tr><td><strong><code>$sscanf</code> / <code>$fscanf</code> (21.3.4.3)</strong></td><td>Integral (<code>%d</code>, <code>%h</code>/<code>%x</code>, <code>%o</code>, <code>%b</code>, <code>%c</code>) and real (<code>%e</code>/<code>%f</code>/<code>%g</code>) conversions; string literals, packed integrals, and <code>string</code> variables as source and format</td><td><code>%s</code> string outputs; <code>%t</code> time scaling</td></tr><tr><td><strong><code>$sformat</code> / <code>$swrite</code> (21.3.3)</strong></td><td><code>string</code> and packed integral destinations (<code>$sformatf</code> returning <code>string</code>)</td><td>Unpacked arrays of <code>byte</code> as destinations</td></tr><tr><td><strong><code>%p</code> formatted output (21.2.1.6)</strong></td><td>Integrals, reals, strings, class handles, packed structs (without side-effecting calls), unpacked struct variables/members/class properties (without dynamic container members), enums, and containers (dynamic array, queue, associative) of those scalars/unpacked structs/enums in procedural bodies (integral elements ≤ 64 bits; integral, <code>string</code>, or scalar-enum associative keys)</td><td>Enum values returned by function calls (or calls with effects) or popped from queues; packed unions; packed structs returned by a function call or computed by a side-effecting call; packed arrays of enums; fixed-size unpacked arrays; structs with <code>real</code> or dynamic-container members; aggregate function results; containers with elements &gt; 64 bits, <code>real</code> elements, other aggregates, or packed-enum/class-handle keys <em>(for run-time format <code>%p</code>, see <a href="#deviations-standard-code">Deviations affecting standard-conforming code</a>)</em></td></tr><tr><td><strong><code>$test$plusargs</code> / <code>$value$plusargs</code></strong></td><td>Packed integral or string-literal queries; integer conversions into packed integrals, and <code>%s</code> into packed integrals or <code>string</code> variables</td><td><code>real</code> conversions; <code>string</code> variable as the format/query argument; non-<code>%s</code> conversion into a <code>string</code> destination</td></tr><tr><td><strong>Time queries, <code>$timeformat</code>, and <code>%t</code></strong></td><td><code>$time</code>, <code>$stime</code>, <code>$realtime</code>, <code>$timeformat</code> (20.4.3; up to 4096 decimal places/width; see <a href="#time-and-precision">Time and precision</a>), <code>%t</code> on numeric values; <code>$timeunit</code>, <code>$timeprecision</code>, <code>$printtimescale</code> on modules/instances</td><td><code>%t</code> of a <code>string</code> value; <code>$timeunit</code>/<code>$timeprecision</code>/<code>$printtimescale</code> on selected instance array elements or generate paths; a scope time unit finer than the design&#39;s global precision</td></tr></tbody></table><h2 id="narrow-limitations" tabindex="-1">Narrow limitations in otherwise supported features <a class="header-anchor" href="#narrow-limitations" aria-label="Permalink to &quot;Narrow limitations in otherwise supported features {#narrow-limitations}&quot;">​</a></h2><ul><li><strong>Design structure:</strong><ul><li>Non-ANSI port expressions such as <code>module m({a, b}, c[3:0], .p(d))</code> (<a href="https://github.com/celox-sim/celox/issues/1953" target="_blank" rel="noreferrer">#1953</a>); plain non-ANSI ports (a header of port names with body declarations) are supported.</li><li>Non-constant ANSI <code>input</code> port defaults (23.2.2.4), defaults on non-<code>input</code> ports, and unpacked-structure port defaults; constant singular <code>input</code> port defaults are supported (constant unpacked-array <code>input</code> port defaults warn via <code>unpacked_port_default</code>, rejected in strict mode).</li><li>Implicit nets declared by port connections of an instance inside a generate block (6.10): an input connection reading one is rejected, and one driven only by outputs becomes a net of the module rather than of the block.</li><li>Instance arrays that are multidimensional, have a negative bound, or exceed 4,095 elements.</li><li>Package nets (<a href="https://github.com/celox-sim/celox/issues/1146" target="_blank" rel="noreferrer">#1146</a>); a package variable cannot be a clock or reset.</li><li>Wildcard imports (26.3): a module, interface, program, or package scope, a generate block, and a procedural block each bind a name once for their whole body (<code>export p::x;</code> binds it in the package), not per reference. References covered by one binding that denote different declarations at their positions are rejected (<a href="https://github.com/celox-sim/celox/issues/4646" target="_blank" rel="noreferrer">#4646</a>); a name that an earlier reference imported through a wildcard import stays bound to that declaration after a later wildcard import that also declares it, as the standard specifies. A block-local initializer reading a package variable through the block&#39;s own wildcard import is also rejected (<a href="https://github.com/celox-sim/celox/issues/4350" target="_blank" rel="noreferrer">#4350</a>).</li><li>Only one source file may declare <code>$unit</code> variables.</li></ul></li><li><strong>Types and expressions:</strong><ul><li>Enum methods (<code>first</code>, <code>next</code>, …) on an element of a packed array of enums (<a href="https://github.com/celox-sim/celox/issues/2417" target="_blank" rel="noreferrer">#2417</a>).</li><li>Constant out-of-range part-select reads, and constant out-of-range part-select writes to an array element or an inner packed dimension (<a href="https://github.com/celox-sim/celox/issues/88" target="_blank" rel="noreferrer">#88</a>). Partial out-of-range constant writes to plain packed vectors (e.g., <code>q[9:6] = v</code> on <code>logic [7:0] q</code>, writing only <code>q[7:6]</code>) and all run-time selects follow the standard.</li><li>Run-time part-selects and element selects of a member of an element of a packed array of structures that is itself a member of a packed structure, such as <code>s.regs[i].q[j +: 4]</code>.</li><li>Reduction operators in parameter expressions (<a href="https://github.com/celox-sim/celox/issues/456" target="_blank" rel="noreferrer">#456</a>).</li><li>Type operator (6.23): comparing a type reference with a value, range items in a <code>case</code> on a type, and applying <code>type(...)</code> to an expression that reads a port or to any expression in a generate block.</li><li><code>$typename</code> <a id="type-names"></a> (20.6.1): rejects types without one exact spelling instead of inventing system-generated names — anonymous enumerations, structs, and unions, soft and tagged unions, unpacked structures with unpacked array members, packed arrays of enumerations or of signed typedefs, classes with non-integral value parameters, and operands other than names and data types (such as <code>$typename(a + b)</code>). Virtual interface types (unspecified in 20.6.1) are written as declared (<code>virtual bus_if</code>, <code>virtual bus_if.mp</code>, <code>virtual bus_if#(8, 4)</code>).</li><li>Aggregate parameters as elaboration-time constants: unpacked array parameters hold their value from simulation start; an element of a 1D array parameter (and a select of its packed dimensions unless the element type is a packed array of a signed named type) is an elaboration-time constant only when elements are packed integrals ≤ 127 bits without X/Z bits and the array has ≤ 4,096 elements; a member of a packed-struct parameter is an elaboration-time constant unless wider than 127 bits or containing X/Z bits; whole unpacked arrays and other elements/members cannot be used where an elaboration-time constant is required.</li></ul></li><li><strong>Processes and subroutines:</strong><ul><li>Nonblocking assignments inside <code>always_comb</code> (<a href="https://github.com/celox-sim/celox/issues/453" target="_blank" rel="noreferrer">#453</a>) and <code>always_latch</code> (<a href="https://github.com/celox-sim/celox/issues/431" target="_blank" rel="noreferrer">#431</a>); use blocking assignments there.</li><li>Package and <code>$unit</code> timed tasks with <code>static</code> arguments.</li><li>Constructing or extending the built-in <code>process</code> class; suspending a process&#39;s own thread or calling <code>await()</code> from a function.</li><li>Loops: procedural loops unroll at most 10,000 iterations; combinational loops with a run-time trip count must be counted <code>for</code> loops; loop-generate constructs within one module are rejected past 1,000,000 iterations in all; <code>genvar</code> updates using bitwise compound operators (<a href="https://github.com/celox-sim/celox/issues/455" target="_blank" rel="noreferrer">#455</a>) and recursive constant-function expansion in generate constructs are rejected.</li><li><code>final</code> procedures <a id="final-procedures"></a>: timing controls, calls to user tasks (including through functions), and functions that schedule events after returning (13.4.4) are rejected; detached <code>fork … join_none</code> children declared in a <code>final</code> procedure are initialized but never start (see <a href="#celox-execution-model">Execution model</a>).</li><li>Named subroutine arguments: calls whose selection indices have procedural effects, and method defaults using the receiver in an <code>always_comb</code> or <code>assign</code> call when the receiver or an earlier argument reading the object has effects.</li><li><code>%m</code> (21.2.1.5) in a subroutine that runs in another instance&#39;s code (a hierarchical call, a call through a virtual interface or an interface port, an override of a class of a module) names the subroutine&#39;s own instance, except in two shapes where it names the calling instance: a subroutine imported through a port of an interface without data members, and an override of a class of a module that reads no item of the module (<a href="https://github.com/celox-sim/celox/issues/4642" target="_blank" rel="noreferrer">#4642</a>).</li></ul></li></ul><h2 id="intentional-deviations" tabindex="-1">Intentional deviations <a class="header-anchor" href="#intentional-deviations" aria-label="Permalink to &quot;Intentional deviations {#intentional-deviations}&quot;">​</a></h2><h3 id="deviations-standard-code" tabindex="-1">Deviations affecting standard-conforming code <a class="header-anchor" href="#deviations-standard-code" aria-label="Permalink to &quot;Deviations affecting standard-conforming code {#deviations-standard-code}&quot;">​</a></h3><p>These accepted IEEE 1800-2023 constructs deliberately behave differently from the standard. Portable code should avoid relying on them:</p><ul><li><p><strong>Program continuous assignments do not run in the Reactive region.</strong> Continuous assignments in a program are evaluated with the design&#39;s combinational logic, and design logic that a program writes settles while the reactive region set runs, so a program resuming after <code>#0</code> reads the new values. IEEE 1800-2023 4.5 evaluates them only once the reactive region set is empty. Icarus, Verilator, and xezim behave as Celox does.</p></li><li><p><strong>Static storage of interface subroutines across modules and virtual interfaces.</strong> A static function or task called through interface ports of several modules keeps its static variables, and the static formals of a task that suspends, once per calling module instead of once per interface instance (13.3.2, 13.4.2; <a href="https://github.com/celox-sim/celox/issues/3739" target="_blank" rel="noreferrer">#3739</a>). Calls through the instance itself and through the port of a single module share one. Likewise, a task or function called through a virtual interface (<code>vif.drive(req)</code>, 25.9) holds static variables per calling scope, and formals belong to each call (even on static subroutines).</p></li><li><p><strong>Procedural <code>assign</code> override timing on indirect writes.</strong> While a procedural <code>assign</code> is active, a write to its variable other than by a plain assignment statement (an output argument, a concatenation target, a delayed nonblocking assignment, or a hierarchical name in another module) is overridden in the time step it happens rather than suppressed, so a process waiting on the variable can observe the written value.</p></li><li><p><strong>Run-time <code>%p</code> format strings simplify non-string values.</strong> When a <code>%p</code> conversion comes from a format string evaluated at run time rather than a compile-time literal, Celox prints <code>string</code> values in quotes and any other value as <code>%0d</code>.</p></li><li><p><strong>No coverage database.</strong> <code>$set_coverage_db_name</code> and <code>$load_coverage_db</code> evaluate their argument and report a compilation warning (<code>no_coverage_database</code> in <a href="./celox-toml.html#diagnostics"><code>[diagnostics]</code></a>); nothing is saved or loaded (19.9; <a href="https://github.com/celox-sim/celox/issues/4294" target="_blank" rel="noreferrer">#4294</a>). Read the coverage of covergroups with <code>Simulation::coverage()</code>. Immediate <code>cover</code> executes its pass statement; assertion coverage and the code coverage of clause 40 are not collected.</p></li><li><p><strong>Clocking events of covergroups.</strong> IEEE 1800-2023 19.3 samples a covergroup &quot;the instant the clocking event takes place, as if the process triggering the event were to call the built-in sample() method&quot;. Celox samples the instances that declarations construct in one of two ways. An event that is one <code>posedge</code> or <code>negedge</code> of a one-bit variable, with or without <code>iff</code>, is an edge-sensitive procedure, <code>always @(posedge clk) c.sample();</code>, one for all the declarations of the type; it runs with the flip-flops of the edge and sees the values before their nonblocking assignments, also at a clock that a flip-flop divides or that a nonblocking assignment toggles. Every other event (<code>@(s)</code>, <code>@(edge s)</code>, a list such as <code>@(posedge a or negedge b)</code>, a named event, a member read through a virtual interface) and every event of a program is a process of its own that waits for it, <code>initial forever begin @(event); c.sample(); end</code>. An instance of such a covergroup that any other <code>new</code> constructs (<code>initial c = new;</code>, a task, a class method, <code>cg a[2] = &#39;{new, new};</code>) joins a list of its type, which the same edge-sensitive procedure walks after the declarations&#39; instances, or one process of the type at any other event (and one more for the list&#39;s fifth instance on): no process is started for it. An instance of a covergroup embedded in a class, or of a covergroup declared in a package or the compilation unit, is sampled by a process that its construction starts, as <code>fork forever begin @(event); c.sample(); end join_none</code> would: it draws no seed from the constructing process (18.14.1) and is no child of it, so <code>wait fork</code>, <code>disable fork</code> and <code>kill()</code> of that process do not see it. They differ from 19.3 as follows:</p><ul><li>Several occurrences before the sampler runs again give one sample: a process that makes the event occur several times without suspending (<code>clk = 1; clk = 0; clk = 1;</code>, <code>-&gt; e; -&gt; e;</code>), and, for a process sampler, occurrences that several processes make in one time step before it runs (two processes raising the terms of <code>@(posedge a or posedge b)</code> at the same time).</li><li>The sample sees a blocking write that the triggering process makes after the triggering write (<code>clk = 1; d = 5;</code> samples <code>d</code> as 5).</li><li>A process sampler misses an occurrence before it first waits: one at time zero by an <code>initial</code> procedure that runs before it, or by the host before the first <code>run_until</code>, and for an instance whose construction starts a process every occurrence until the process that constructs it suspends. An edge sampler samples those, as the flip-flops of the edge run then. An instance in a list is sampled at an occurrence of the time step it is constructed in only if its sampler runs after the construction: one that an <code>always @(posedge clk)</code> constructs is first sampled at the next edge.</li><li>A process sampler at an edge of a variable that the NBA region updates (a divided clock, a clock toggled with <code>&lt;=</code>) runs after the nonblocking assignments of that edge and sees their values, as a process the design writes with <code>initial forever @(...)</code> does (<a href="https://github.com/celox-sim/celox/issues/4771" target="_blank" rel="noreferrer">#4771</a>). So does the process that samples an instance of an embedded covergroup or of a covergroup of a package or the compilation unit.</li><li>An edge sampler beside an edge-sensitive procedure that calls <code>sample()</code> of the same covergroup type runs as a process, and so sees the nonblocking assignments of an edge the NBA region updates, as two such procedures the design writes do (<a href="https://github.com/celox-sim/celox/issues/4771" target="_blank" rel="noreferrer">#4771</a>).</li><li>When a virtual interface property that the event of an embedded covergroup reads (<code>@(posedge vif.clk)</code>) is assigned another interface instance, the wait that is armed already fires once more at the next edge of the old clock; the later ones are on the new one (9.4.2 waits on the new one at once). A task of the class that waits on the same event control does the same (<a href="https://github.com/celox-sim/celox/issues/4791" target="_blank" rel="noreferrer">#4791</a>); a virtual interface variable of a module is followed at once.</li><li>When a handle property whose named event the event names (<code>@(h.e)</code>) is assigned another object, the wait that is armed stays on the event of the object it was armed on, as a process of the source waiting on <code>@(h.e)</code> does and as 15.5.5.1 has it for a wait on an event variable that is assigned: until that event is triggered, the triggers of the new object&#39;s event are no samples.</li></ul><p>Occurrences separated by <code>#0</code> or in different delta cycles are each a sample, and a value that a nonblocking assignment of a blocking clock&#39;s edge updates is sampled before the update, as 19.3 has it.</p></li><li><p><strong><code>$exit</code> outside a program warns.</strong> A <code>$exit</code> call from anywhere other than a program thread is ignored, as 24.7 specifies, and Celox also reports a compilation warning (<code>exit_outside_program</code> in <a href="./celox-toml.html#diagnostics"><code>[diagnostics]</code></a>), including for calls in unused function declarations.</p></li><li><p><strong>UVM DPI functions are built in.</strong> Imports with the C names of UVM&#39;s <code>src/dpi</code> functions bind to Celox&#39;s implementations instead of a user C function; see <a href="#dpi-c-imports">DPI-C imports</a>.</p></li><li><p><strong>Opt-in compatibility modes.</strong> Options in <a href="./celox-toml.html#compatibility"><code>[compatibility]</code></a> (such as <code>legacy_empty_reductions</code> and <code>shared_always_temporary</code>) preserve standard IEEE 1800-2023 semantics by default and deviate only when explicitly enabled.</p></li></ul><h3 id="deviations-nonstandard-code" tabindex="-1">Permissive acceptance of non-standard code <a class="header-anchor" href="#deviations-nonstandard-code" aria-label="Permalink to &quot;Permissive acceptance of non-standard code {#deviations-nonstandard-code}&quot;">​</a></h3><p>Celox intentionally accepts the following non-standard constructs and compatibility extensions. Portable code should avoid relying on them.</p><p><strong>Warn by default, rejected in strict mode (<code>strict = true</code> / <code>--strict</code> / <code>.strict(true)</code>):</strong></p><ul><li><p><strong>A missing <code>static</code> keyword on initialized locals (6.21).</strong> IEEE 1800-2023 6.21 requires an explicit <code>static</code> when a static variable&#39;s declaration specifies an initializer. Celox also accepts the declaration without <code>static</code> with a constant initializer in any procedure, and with a run-time initializer in a procedure that runs once (such as <code>initial</code>), reporting an <code>implicit_static_initializer</code> warning (<code>warn</code> by default, <code>error</code> in strict mode). In an <code>always</code> procedure, a run-time initializer without <code>static</code> or <code>automatic</code> is rejected.</p></li><li><p><strong>Semicolons after an <code>`include</code> filename (22.4).</strong> IEEE 1800-2023 22.4 allows only white space or a comment on the line of an <code>`include</code> directive after its filename. Celox ignores semicolons there (<code>`include &quot;uvm_macros.svh&quot;;</code>), as other simulators do, and reports an <code>include_trailing_semicolon</code> warning (<code>warn</code> by default, <code>error</code> in strict mode). Any other text after the filename is rejected.</p></li><li><p><strong>Default time scales when explicit time scales are mixed (3.14.2.3).</strong> Instead of rejecting designs where only some elements specify or inherit a time scale, Celox reports a <code>mixed_timescale</code> warning (<code>error</code> in strict mode) naming those elements and assigns them 1 ns / 1 ps, as other simulators do.</p></li><li><p><strong>Other warn-by-default compatibility diagnostics.</strong> Duplicate module declarations (<code>duplicate_module</code>), <code>$size</code> on fixed-size interface arrays (<code>interface_array_query</code>), <code>bus.WIDTH</code> parameter shorthand on interface arrays (<code>interface_array_parameter</code>), constant unpacked-array <code>input</code> port defaults (<code>unpacked_port_default</code>, 23.2.2.4), and memories shared between <code>always_ff</code> and another edge process (<code>multiple_always_ff_drivers</code>) warn by default and are rejected in strict mode; see <a href="./celox-toml.html#diagnostics"><code>[diagnostics]</code></a> (alongside <code>inferred_latch</code>).</p></li><li><p><strong>Packed values and unbased fills assigned to fixed-size unpacked arrays (7.6).</strong> With <code>packed_to_unpacked_assignment</code> at <code>warn</code> (the default) or <code>allow</code>, Celox copies an exact-width packed value bit for bit or fills every element with an unbased unsized literal such as <code>&#39;0</code>. Strict mode rejects these assignments and equivalent module port connections (10.8) by default. Use an explicit cast to the array type or an assignment pattern such as <code>&#39;{default: &#39;0}</code>.</p></li><li><p><strong>Procedural <code>force</code> and <code>release</code> on variable selects and unpacked array elements (10.6.2).</strong> <code>nonstandard_force_target</code> warns by default and becomes an error in strict mode for constant bit/part-selects or members of variables and constant-indexed elements (or selections of those elements) of fixed-size unpacked arrays of packed integrals. Forcing an array element can also emit the <code>forced_array</code> diagnostic about the size of the force controls.</p></li><li><p><strong>Vendor alias <code>$psprintf</code> (21.3.3).</strong> Celox interprets it as <code>$sformatf</code> and emits <code>psprintf_alias</code> by default. Strict mode rejects the alias by default.</p></li></ul><h2 id="semantics-worth-knowing" tabindex="-1">Implementation-defined and unspecified behavior <a class="header-anchor" href="#semantics-worth-knowing" aria-label="Permalink to &quot;Implementation-defined and unspecified behavior {#semantics-worth-knowing}&quot;">​</a></h2><p>Where IEEE 1800-2023 leaves a choice to the implementation, or declares an order unspecified or nondeterministic, Celox chooses as follows. Portable code must not depend on these choices.</p><h3 id="constant-widths" tabindex="-1">Constant widths <a class="header-anchor" href="#constant-widths" aria-label="Permalink to &quot;Constant widths {#constant-widths}&quot;">​</a></h3><p>IEEE 1800-2023 lets an implementation limit the width of a vector to no less than 65,536 bits (6.9.1, 7.4.1). A constant value, such as a parameter, the concatenation that gives it or a part-select of it, may have up to 1,048,576 bits. A replication, a constant built bit by bit, and a value inside a constant function call may have up to 65,536 bits. A wider constant is rejected before it is built.</p><h3 id="timing-semantics" tabindex="-1">Event scheduling <a class="header-anchor" href="#timing-semantics" aria-label="Permalink to &quot;Event scheduling {#timing-semantics}&quot;">​</a></h3><p>Clause 4.7 permits either order in the cases below; Celox is deterministic:</p><ul><li>Continuous assignments, combinational processes, and event expressions see a timed process&#39;s writes when that process reaches a timing control or ends. After <code>b = 1; a = 1;</code>, <code>a ^ b</code> has not changed, and a pulse <code>a = 1; a = 0;</code> wakes <code>@(a)</code> but not <code>@(a ^ b)</code>; write <code>#0</code> between the writes to make the pulse visible to an expression wait. Compound waits on fork-shared automatic locals instead observe each supported blocking assignment and statement-call copy-out.</li><li>A waiter sees every value one evaluation of <code>always_comb</code>, <code>always @*</code>, or an edge-triggered process writes, including one a later write overwrites (4.3, 9.4.2). Through a child instance&#39;s output port — a continuous assignment (23.3.3) — a waiter in the parent sees only the settled value.</li><li>An <code>expr iff condition</code> item (9.4.2.3) is judged at each write of <code>expr</code> when both are variables, so in one process <code>clk = 1; en = 0;</code> is an event and <code>en = 0; clk = 1;</code> is none. When <code>expr</code> or the condition is a general expression or a net, or <code>expr</code> is written by a flip-flop domain (<a href="https://github.com/celox-sim/celox/issues/1830" target="_blank" rel="noreferrer">#1830</a>), the condition is judged when the occurrence is detected, after combinational logic settles.</li><li>A <code>wait</code> condition reading class properties is re-checked after any store of a property it reads — through any handle and after every <code>randomize()</code> call — including stores of the same property of another object or of the value already held, so it may be checked more often than the minimum (9.4.3).</li><li>With an asynchronous reset, a <code>$past</code> history tick is a run in which the clock has left the level it had before the time slot; a clock that returns to that level within the slot does not move the history. Multiple clocking-event transitions within one time step are undefined in concurrent assertions (16.5).</li></ul><h3 id="time-and-precision" tabindex="-1">Time and precision <a class="header-anchor" href="#time-and-precision" aria-label="Permalink to &quot;Time and precision {#time-and-precision}&quot;">​</a></h3><ul><li>The implementation default time scale is 1 ns / 1 ps. A <code>Simulation</code> counts time in the design&#39;s global time precision (3.14.3), 1 ps by default, so <code>%t</code> reports picoseconds in a design without time scales.</li><li><code>$timeformat</code> (20.4.3) sets the units, decimal places, suffix and minimum field width of the <code>%t</code> conversions after it, in every output and in <code>$sformatf</code>; the time rounds half away from zero, and the width of a conversion such as <code>%0t</code> replaces the minimum field width. The suffix is a string literal, NUL characters included. An <code>always_comb</code>, <code>always_latch</code> or <code>always @*</code> that calls it, also through a subroutine, runs as a process: once at time zero (except <code>always @*</code>), then after each change of what it reads. A units number outside 2 to -15 or a negative precision or field width computed at run time ends the simulation with an error, as a constant one fails the analysis; Celox prints at most 4,096 decimal places and pads to at most 4,096 characters, and a larger precision or field width is an error.</li><li>A class or subroutine declared in the compilation unit (<code>$unit</code>) uses the compilation unit&#39;s time unit and precision. A <code>`timescale</code> directive does not set those (3.14.2.3), so they are the default 1 ns / 1 ps unless <code>$unit</code> declares <code>timeunit</code>/<code>timeprecision</code>. Verilator applies the last <code>`timescale</code> instead. For portable code, declare <code>timeunit</code> in <code>$unit</code>. A precision finer than the global precision rounds to whole simulation steps.</li><li><code>final</code> procedures run sequentially in a deterministic but unspecified order. Relative order of package and module variable initializers that call constructors or functions is likewise unspecified (6.8, 10.5); do not rely on it.</li></ul><h3 id="random-numbers" tabindex="-1">Random numbers <a class="header-anchor" href="#random-numbers" aria-label="Permalink to &quot;Random numbers {#random-numbers}&quot;">​</a></h3><ul><li><code>$urandom</code> uses a deterministic 32-bit linear congruential generator (18.13.1, 18.14); its default seed and sequence are implementation-defined and need not match other simulators. <code>$random</code> and the <code>$dist_*</code> functions follow Annex N, so their sequences match other implementations of that annex. The random-state strings of <code>process</code> and of class objects (<code>get_randstate</code>, 18.13.4) are opaque and specific to Celox; <code>set_randstate</code> (18.13.5) accepts only a string that <code>get_randstate</code> returned and otherwise ends the simulation with an error.</li><li>In combinational procedures, random draws occur when the process activates; repeated evaluation with unchanged inputs does not advance the stream.</li><li>Constrained <code>randomize()</code> searches for a satisfying assignment with the object&#39;s seed and updates all selected properties together; the search does not guarantee a uniform distribution (<a href="https://github.com/celox-sim/celox/issues/2187" target="_blank" rel="noreferrer">#2187</a>). Proved infeasibility returns <code>0</code>, preserves the properties, and skips the post-hook (18.6.3); resource exhaustion is a runtime error.</li><li>Soft constraints (18.5.13) are tried from the highest priority down (18.5.13.1): each is kept when the hard constraints and the soft ones kept before it allow it, and is otherwise discarded; a <code>disable soft</code> discards the lower soft constraints that name its variable (18.5.13.2). The search for each keeps the seed, so the choice is reproducible. A soft <code>dist</code> constrains its operand to its items of nonzero weight; while it is kept, its weights shape the choice as those of a hard one do (18.5.3), and a discarded one has no effect on it.</li><li>A 4-state <code>rand</code> property takes a 2-state value. The X and Z bits of a 4-state state property, of the value of a function a constraint calls whose type is 4-state, and of a 4-state caller-scope input of inline constraints or of <code>std::randomize() with</code>, follow the 4-state semantics of each operation (11.4): a constraint or guard whose truth they decide ends the simulation with an error (18.3), one they do not decide, as through a mask, a select or an <code>&amp;&amp;</code> a known 0 decides, takes its value, and such a guard is evaluated before solving (18.5.13). Where the truth also depends on random variables, the solution found decides whether they reach it.</li><li><code>solve before</code> (18.5.9) leaves the solutions as they are, and the search does not order its choices by it; a circular order is not diagnosed.</li><li>A function a constraint calls (18.5.11) runs as any call of it does, the override of the object&#39;s class included, after the random variables in its arguments are solved by the constraints that name only them; its value is state to the other constraints, so they can leave the call no solution, and a random variable it reads that is no argument has its value before the call.</li><li><code>randsequence</code> (18.17): a production of several rules picks one by their weights, 1 unless given, from the thread&#39;s random number generator (18.14.2). <code>rand join</code> interleaves its productions&#39; items at random from the same generator; 18.17.5 gives the bias no formula, so Celox evaluates it once and, at each step, with probability |2 × bias − 1| advances a production with the fewest items left (bias below 0.5) or the most (above 0.5), and otherwise any production with items left, each as likely (0.5 prefers no length; 0.0 and 1.0 always prefer the shortest and longest).</li><li>Array <code>shuffle</code> draws from the calling process&#39;s random stream.</li></ul><h3 id="coverage" tabindex="-1">Coverage <a class="header-anchor" href="#coverage" aria-label="Permalink to &quot;Coverage {#coverage}&quot;">​</a></h3><p><code>Simulation::coverage()</code> and <code>Simulator::coverage()</code> report every covergroup type that has an instance, with its instances, their numbers of samples and the coverage <code>$get_coverage</code> gives. Reading the report changes nothing and advances no time.</p><ul><li><strong>A covergroup type belongs to its elaborated scope.</strong> Instances of a module with the same parameter values share the covergroup types the module declares, as they share its typedefs; 6.22 makes them types of each instance. Elaborations with other parameter values declare types of their own, which the report lists under one name. A covergroup of a package is one type of the design, and one of a compilation unit a type of its source file.</li><li><strong><code>sample()</code> on <code>null</code> samples nothing</strong>, for an embedded covergroup that the constructor did not create (19.4) and for any other covergroup variable. <code>get_coverage()</code> and <code>type_option</code> through a handle are those of the type and do not read the handle; <code>get_inst_coverage()</code>, <code>start()</code>, <code>stop()</code>, <code>set_inst_name()</code> and <code>option</code> on <code>null</code> are a runtime error. The expression that names the covergroup of an operation of the type is not evaluated either: in <code>f().get_coverage()</code> or <code>f().type_option.weight</code><code>f</code> is not called, as a static member of a class is read without its object (8.9, 19.7.1).</li><li><strong>Options assigned in a procedure</strong> take the value converted to the type 19.10 gives the member, as a variable of that type takes it (a <code>real</code> is rounded, x and z bits are 0), and count from then on: the hits an instance has are those it had, and <code>at_least</code>, <code>weight</code> or <code>merge_instances</code> change only how they are counted. <code>option.at_least</code> of a covergroup is that of each of its coverpoints and crosses that does not assign its own, also when a procedure assigns it after the item read it (Table 19-2); <code>weight</code>, <code>goal</code> and <code>comment</code> of the covergroup are not those of its items (19.7). <code>goal</code> changes no number and is shown in the report. A negative weight ends the simulation with an error (&quot;shall be a non-negative integral value&quot;, Table 19-1). <code>set_inst_name(s)</code> assigns <code>option.name</code>, which is <code>&lt;type&gt;#&lt;n&gt;</code> until it is assigned. The options of the instances and of the types are part of a checkpoint.</li><li><strong><code>start()</code> and <code>stop()</code></strong> set whether the covergroup and each of its coverpoints and crosses collect, each on its own; an instance starts collecting. An item counts a sample where it and the covergroup collect: a stopped covergroup evaluates nothing of a sample, and a stopped coverpoint leaves its crosses without the sample, as one whose guard is false does, and reports no hit of its illegal bins.</li><li><strong>With two arguments</strong> <code>get_inst_coverage</code> gives the covered bins and the bins of the item, or of all items of the instance, and <code>get_coverage</code> their sums over the instances (19.8); with <code>type_option.merge_instances</code><code>get_coverage</code> gives those of the union of the bins of the instances (19.11.3). Without <code>merge_instances</code>, these sums count the bins of every instance, also of one whose <code>option.weight</code> is 0, which the coverage the method returns leaves out (19.11.3). With <code>type_option.merge_instances</code> and without <code>option.get_inst_coverage</code>, <code>get_inst_coverage</code> gives what <code>get_coverage</code> does (Table 19-1); without <code>merge_instances</code> it is always the coverage of the instance.</li><li><strong><code>option.detect_overlap</code></strong> warns of each pair of overlapping bins of a coverpoint with a <code>$warning</code> report of the <code>new</code> that constructs the instance (Table 19-1).</li><li><strong><code>type_option.strobe</code></strong> has no effect on a covergroup without a clocking event: it &quot;only applies to the scheduling of samples triggered by a clocking event&quot; (19.3). A nonzero value on one with a clocking event is rejected (<code>covergroup strobe sampling</code>).</li><li><strong>The instance is sampled, not the variable.</strong> A declaration <code>cg c = new;</code> of a covergroup with a clocking event samples the instance it constructs at each occurrence of the event, whatever <code>c</code> holds later: <code>c = null</code> or <code>c = d</code> neither stops that nor samples another instance twice, and the instance is never freed. So is an instance that any other <code>new</code> constructs, from its construction on: assigning <code>c = new;</code> again samples both instances. An embedded covergroup is sampled until the property of its object holds another instance, which the <code>new</code> method of its class constructs there (19.4 allows the assignment in that method alone): the former instance counts no sample of the event from the next occurrence on. The sampler holds the instance, and the object of an embedded one, for the rest of the simulation. <code>sample()</code> and the other methods of 19.8 apply to such an instance as to any (&quot;These methods can be invoked procedurally at any time&quot;): <code>sample()</code> samples it once more, and a stopped instance counts no sample of its event. No sample is taken before the first occurrence of the event, also of a change event (<code>@(s)</code>) in two-state simulation. In four-state simulation an assignment at time zero that makes a variable 0 or 1 is an edge (Table 9-2) that an edge sampler samples, as the flip-flops of the edge run then; a declaration initializer is none (10.5).</li><li><strong><code>ref</code> arguments read the variables of the declaration.</strong> A covergroup with <code>ref</code> arguments (19.3 treats them as <code>const ref</code> ones) is constructed by declarations of a module or a program with <code>new</code> as their initializer, each with its own actuals: <code>cg a = new(bus_a), b = new(bus_b);</code>. Each sample of an instance reads the variables its actuals name then: at the clocking event of the covergroup, and through <code>sample()</code> on the variable of the declaration (<code>a.sample();</code>) in any procedure, task, function or method of a class of the scope, which is how a covergroup without a clocking event samples them (19.8). An option that reads such an argument reads it when <code>new</code> runs. A bin value, a bin array size, a <code>with</code> filter, a set expression or an <code>intersect</code> list may not read one (&quot;Only constant expressions ... or non-ref arguments to the covergroup are allowed to be used as variables in a covergroup_expression&quot;, 19.5): that is an error. An actual is a variable, a <code>logic</code> variable a continuous assignment drives included, a static property of a class, a member of an unpacked structure variable, an unpacked array (<code>ref logic [3:0] bus_event[0:7]</code>) or an element of one at a constant index (in a generate loop, <code>bus_event[i]</code>); a net, a select of one, an expression or a constant is an error (13.5.2). As the samples through the variable pass the actuals of its declaration, nothing but the initializer may write the variable; <code>get_inst_coverage()</code>, <code>get_coverage()</code>, <code>start()</code>, <code>stop()</code>, the options and the other methods take the instance through any handle. A <code>ref</code> argument of <code>with function sample</code> is passed by each call of <code>sample()</code>, through any handle.</li><li><strong>A program samples in the Reactive region set.</strong> The instance a declaration of a program constructs is sampled after the nonblocking assignments of the design at the same event, as every process of a program is scheduled (24.3.1): at a rising edge it sees the values the flip-flops of the edge assigned. 19.3 can be read to sample where the event occurs instead.</li><li><strong>A covergroup without items has no coverage.</strong> <code>get_inst_coverage()</code> and <code>get_coverage()</code> of a covergroup that declares no coverpoint or cross are 0, and it takes no part in <code>$get_coverage()</code>, which is 100 when no covergroup of the design does (19.11).</li><li><strong>Bin values are compared as values of the coverpoint type (19.5.7).</strong> A value the type does not have takes no part in its bin, and a range takes part with the values the type has. For a constant the build warns (<code>covergroup_bin_value</code>); for a value that an argument of the covergroup gives, the <code>new</code> that constructs the instance issues a <code>$warning</code> report with every such value of the instance, and one for <code>option.auto_bin_max</code> below 1, which makes one automatic bin. A range whose bounds differ in signedness is read in their common type, as the operands of a binary operator are (11.8.1): in <code>[-1:8&#39;d5]</code> the bound -1 is a large unsigned value, which is warned of too. An unsigned value on a signed coverpoint stands for the value its bits read as: <code>8&#39;hFF</code> is -1 on an 8-bit signed coverpoint.</li><li><strong>x and z.</strong> A sample with an x or z bit is in no automatic bin (19.5.3). On a coverpoint of a 4-state type, a bin value written with x or z bits holds exactly the samples with those bits; on one of a 2-state type it takes no part, with a warning (19.5.4 and 19.5.7 differ here). A bound of a range with such bits drops the range. In two-state simulation no sample has such a bit.</li><li><strong>An illegal bin hit is an error report.</strong> A sample of a value of an <code>illegal_bins</code> bin whose guard holds issues a report of <code>$error</code> severity that names the bin, its coverpoint, its covergroup, the instance and the value (19.5.6); a sample that hits several such bins reports them in one. The simulation goes on, the sample counts in no <code>bins</code> bin, and the run ends as any run with an error report does. The values of an illegal bin are values of no other bin whether or not its guard holds, and so are those of <code>ignore_bins</code>: a guard on these gates the hit count of the bin itself, which the report shows, and that of an illegal bin its error.</li><li><strong>Bins are made when an instance is constructed</strong> (19.5.1): a bin for each value (<code>b[]</code>) in the order the values first appear, named <code>b[value]</code>; <code>b[N]</code> as 19.5.1 distributes the values, named <code>b[0]</code> to <code>b[N-1]</code>. The values of <code>ignore_bins</code> and <code>illegal_bins</code> are taken once the values are distributed, and a bin that is left without a value takes no part in the coverage and is not listed (19.5.5, 19.11.1). A number of bins <code>N</code> that is not positive is an error of the build for a constant and ends the simulation with an error for an argument.</li><li><strong><code>default</code> bins</strong> count the samples that are in no bin of a declaration of their coverpoint, <code>ignore_bins</code> and <code>illegal_bins</code> among those: an ignored value is no <code>default</code> value. A sample with x or z bits that no bin lists with those bits is such a sample, so <code>illegal_bins b = default</code> reports it in four-state simulation. A <code>default[]</code> array has a bin for each of the first 4,096 values that are sampled, named with the value (a value with x or z bits as a sized binary literal, <code>b[4&#39;b1x0z]</code>); the samples of further values are counted in <code>omitted_bins</code> of the report. A coverpoint with a <code>default</code> bin of <code>bins</code> has no automatic bins, and where it declares no other <code>bins</code> it has no bin to cover (19.11.1).</li><li><strong>Wildcard bins</strong> (19.5.4) list the values their x, z and <code>?</code> bits stand for, so that ignored and illegal values are taken from them as from any bin. A value of more than 65,536 ranges of values (<code>4&#39;b11??</code> is one range, <code>4&#39;b1??1</code> four) is instead matched when it is sampled: what is counted is the same, but <code>ignore_bins</code> and <code>illegal_bins</code> take no value from such a bin, and as a value of <code>ignore_bins</code> or <code>illegal_bins</code> it leaves no bin without a value; the <code>new</code> of the instance warns where that can matter. Only one bin without a <code>with</code> filter may have such a value. A range of a wildcard bin whose bounds have x or z bits is the values from its lowest low bound to its highest high bound.</li><li><strong><code>with</code> filters</strong> (19.5.1.1) are asked about each value of their bin when an instance is constructed, at most 1,048,576 values; a bin whose values depend on an argument and are more ends the simulation with an error. Before <code>with</code>, the name of a coverpoint of an enumeration stands for its named values, as its automatic bins do (19.5.3). What the expression reads beside <code>item</code> and constants, such as an argument of the covergroup, a string among them, or a constant of the object of an embedded covergroup, decides the bins with the values of the bin: an instance that is constructed with the values an earlier one of its type was constructed with takes its bins without evaluating the expression again (19.5.1.1 allows caching). A filter that reads an object, whose state those values do not tell, is evaluated by every construction: one that calls a method of the class of an embedded covergroup that is not static, which may read the constants of its object (19.5), and one with a handle among its operands, such as <code>h.ok(item)</code> or <code>f(h, item)</code>. Any other function is taken to read its arguments and global constants only, as 19.5 requires. The filter of one <code>bins</code> bin (no array) whose values are constants and more than that, such as <code>bins b = cp with (...)</code> on a coverpoint of more than 20 bits, is evaluated for the sampled value at each sample instead. Such a bin always counts as a bin with values, also when the expression keeps none, and <code>ignore_bins</code> and <code>illegal_bins</code> take from it without regard to the expression.</li><li><strong>Set expressions</strong> (19.5.1.2). The elements of an array parameter (<code>localparam int S [3] = &#39;{1, 4, 6};</code>, also of a package) are the values of the bin as if it listed them, and the build warns of those the coverpoint type has not. The elements of a dynamic array or a queue, such as a function returns for the arguments of the covergroup, and of a constant array of the class of an embedded covergroup are read when an instance is constructed, which then warns. The first element is the first value: <code>bins b[2] = S</code> of four elements has the first two in <code>b[0]</code>.</li><li><strong>Tolerance ranges</strong> (11.4.13) take integral operands; the tolerance of <code>[A +%- B]</code> is <code>A * B / 100</code> as integers divide, towards zero, which is what the standard&#39;s conversion of <code>A*B/100.0</code> gives for the values a <code>real</code> holds exactly.</li><li><strong>Automatic bins of a signed coverpoint start at its lowest value</strong>, and are named by their values: <code>auto[3]</code>, <code>auto[0:3]</code>, <code>auto[NAME]</code> for an enumerator. A coverpoint without a label has the name of its variable where its expression is that name alone (19.5). Of any other expression, a member of an object (<code>t.kind</code>) and a select of a variable among them, it is shown as <code>$point&lt;n&gt;</code>, with the number of the coverpoint in the covergroup from 1.</li><li><strong>Crosses</strong> (19.6). The coverpoint of a variable that a cross crosses and that is no coverpoint of the covergroup is named by the variable and follows the coverpoints the covergroup declares, one for each variable however many crosses cross it; it takes part in the coverage of the covergroup as they do. A cross without a label is shown as <code>$cross&lt;n&gt;</code>, with the number of the cross in the covergroup from 1. An automatic bin of a cross is named by its bins, <code>&lt;a1,auto[3]&gt;</code>. The bins of a cross are those of its coverpoints that take part in their coverage: a <code>default</code>, ignored or illegal bin and one left without a value have no cross products (19.6, 19.11.1).</li><li><strong>A cross is sampled where each of its coverpoints counts the sample</strong> in such a bin (19.6.1: &quot;every coverage point in the cross matches its corresponding bin&quot;). A coverpoint whose guard is false, or whose value is in no bin of it that takes part, or only in bins whose guard is false, leaves its crosses without the sample. A sample in two bins of a coverpoint is two cross products of its crosses. A cross bin counts a sample once however many of its cross products it is, and a cross bin whose guard is false counts nothing; its cross products stay those of no automatic bin.</li><li><strong>Cross bins.</strong> The values of an <code>intersect</code> list are resolved as those of a bin of the coverpoint of its <code>binsof</code> (19.5.7), with the warnings of bin values: of the build for a constant, of the <code>new</code> of the instance for a value an argument gives. <code>intersect</code> keeps the bins that hold one of them after ignored and illegal values are taken from the bins. The cross products of <code>ignore_bins</code> and <code>illegal_bins</code> are those of no other bin (19.6.2, 19.6.3), and a declared <code>bins</code> bin left without a cross product takes no part in the coverage. A sample of an illegal cross product issues a report of <code>$error</code> severity that names the bin, the cross, the covergroup, the instance and the cross product, as an illegal value of a coverpoint does. With <code>option.cross_retain_auto_bins</code> 0 a cross that declares any bin, <code>ignore_bins</code> and <code>illegal_bins</code> among them, has no automatic bin (Table 19-1), so a cross with only <code>ignore_bins</code> has no bin and takes no part in the coverage (19.11.2).</li><li><strong>Crosses are not listed product by product.</strong> A report lists the bins a cross declares, its automatic bins that were sampled, then as many others as <code>option.cross_num_print_missing</code> asks for, at most 4,096; the number of the others is in <code>omitted_bins</code>. A construction ends the simulation with an error where the bins of a cross tell more than 1,048,576 classes of cross products apart, where a cross has more than 2^128 cross products, and where sorting the cross products into its bins takes more than 2^26 steps; with <code>type_option.merge_instances</code>, a query of the coverage of the type does where uniting the automatic bins of its instances takes more than 2^26 steps (the report counts them however long it takes). An <code>intersect</code> list that meets values of a bin that only a sample sorts, those of an ignore or illegal wildcard value of more than 65,536 ranges or of a bin whose <code>with</code> filter is evaluated at each sample, is not supported: the construction ends the simulation with an error that says so.</li><li><strong>A coverpoint has at most 1,048,576 bins.</strong> A construction that would make more ends the simulation with an error, as does a sample whose values the heap cannot take as those of the coverpoints of its type, which only an error of Celox causes; such a sample is not counted.</li><li><strong>Sampling calls a function of a coverpoint once.</strong> The guards and the expressions of all coverpoints of a <code>sample()</code> are evaluated in the order of their declaration before any of them is counted, so a function among them may itself call <code>sample()</code>.</li><li><strong>Coverage is cumulative and instances are never freed.</strong> The samples of an instance stay in the coverage of its type and in the report when nothing refers to it any more; the report marks it as no longer live. A testbench that constructs a covergroup for each transaction grows the report by an instance each time.</li><li><strong>Constructing a covergroup draws no random number</strong>, so adding one to a procedure or to a class constructor leaves its random stimulus unchanged (18.14.1), also one with a clocking event, whose sampler takes no seed. A covergroup variable declared with an initializer in a module is a process of its own, as a class variable with one is, and takes a place in the order in which processes are seeded.</li><li><strong>Coverage is part of a checkpoint and not of a state file.</strong><code>Simulation::restore</code> restores the coverage of the checkpoint; <code>save_state</code> and <code>load_state</code> fail with <code>StateError::Coverage</code> once a covergroup was constructed.</li><li>Instances are named <code>&lt;type&gt;#&lt;n&gt;</code> in the report, numbered from 0 in the order of their construction within the type.</li></ul><h3 id="host-dependent-results" tabindex="-1">Host-dependent results <a class="header-anchor" href="#host-dependent-results" aria-label="Permalink to &quot;Host-dependent results&quot;">​</a></h3><ul><li><code>$ferror</code> codes and wording are host dependent; Celox also exposes a failed <code>$fopen</code>&#39;s details through FD 0.</li><li><code>$system</code> returns the C <code>system()</code> value, including the host platform&#39;s exit-status encoding (20.17.1). Relative file paths use the host process&#39;s working directory.</li><li><code>$fgets</code> with no bytes read leaves the destination unchanged; 21.3.4.2 specifies the returned count but not that destination value.</li></ul><h2 id="celox-execution-model" tabindex="-1">Celox execution model <a class="header-anchor" href="#celox-execution-model" aria-label="Permalink to &quot;Celox execution model {#celox-execution-model}&quot;">​</a></h2><p>These choices belong to Celox&#39;s API, not to SystemVerilog; they decide which designs need the timed <code>Simulation</code> API and what the host can observe.</p><ul><li><strong><code>Simulator</code> runs no processes.</strong> Constant initialization applies to both APIs. <code>final</code> procedures, <code>initial</code> blocks that read design state or call system tasks, processes with timing controls, and <code>always</code> blocks whose sensitivity list is neither <code>@*</code> nor exactly the variables the statement reads run as processes and need <code>Simulation</code>. Building a <code>Simulator</code> for such a design fails with <code>SimulatorErrorKind::ProcessRequiresSimulation</code>, naming the first process and its source location. An <code>always</code> whose list (or part-selects) covers exactly what the statement reads, with no timing control, nonblocking assignment, subroutine or system task call, self-read, or repeated store, simulates like <code>always @*</code> in both APIs; so does a flip-flop-shaped edge-sensitive <code>always</code>. <code>Simulator::tick</code> drives the rising edge of its event only; a <code>Simulation</code> runs every edge. A <code>Simulator</code> call is one time slot for <code>$sampled</code> and deferred assertions, and <code>$time</code> returns 0.</li><li><strong>Covergroups.</strong> A covergroup variable declared with an initializer in a module or program (<code>cg c = new;</code>) is constructed by a process at time zero, which needs <code>Simulation</code>: building a <code>Simulator</code> for such a design fails as for any process. Under <code>Simulator</code>, construct the covergroup in a clocked procedure (<code>always @(posedge clk) begin if (c == null) c = new; c.sample(); end</code>). A covergroup variable of a module is a handle in the state of the design, as a class handle is: the compiled scheduler of a <code>Simulation</code> then calls into the host at the end of each time slot, or returns to it there where it has no such call (it has one on x86-64), also when nothing constructs the variable. Under <code>Simulation</code>, sampling from clocked logic adds only the calls that sample. Under <code>Simulator</code>, a clock whose clocked procedures construct or sample a covergroup also loses the <code>tick</code> that is one run of its clock domain: as any call into the host from clocked logic, the call is taken for one that may read the clock, so each <code>tick</code> moves the clock to its active level and back, which each tick pays beside the calls that sample. <code>sample()</code> from <code>always_comb</code> or <code>always @*</code> samples at each evaluation of the procedure and makes the design evaluate its whole combinational logic at each settle instead of the part a change reaches. Earlier releases ignored <code>cg c = new;</code>, so such a design built as a <code>Simulator</code> and had no handle in its state. An instance sampled at the clocking event of its type (<code>cg c = new;</code> of a <code>covergroup cg @(posedge clk);</code>) needs <code>Simulation</code>, as its declaration is a process. At one edge of a one-bit variable it is sampled by an edge-sensitive procedure, which costs what <code>always @(posedge clk) c.sample();</code> costs, one for all the declarations of the type; at any other event by a process of each declaration, which costs what <code>initial forever begin @(event); c.sample(); end</code> costs, a kernel of the compiled scheduler (one that waits for a named event, or one of a program, runs in the runtime&#39;s loop). Each declaration adds the hidden handle variable that holds the instance, <code>%covergroup_site&lt;n&gt;</code>, which the signal listings and waveforms show, as they show the hidden variables of delayed continuous assignments. An instance of such a type that any other <code>new</code> constructs needs <code>Simulation</code> too and costs about what an instance of a declaration costs: the samplers of the type walk the list of the type, four hidden handle variables (<code>%covergroup_instance&lt;n&gt;_&lt;k&gt;</code>), a count (<code>%covergroup_instance_count&lt;n&gt;</code>) and a queue (<code>%covergroup_instances&lt;n&gt;</code>) for the fifth instance on, whose elements each sample reads with calls into the host. The list holds its instances for the rest of the simulation. An instance of a covergroup embedded in a class, or of a covergroup of a package or the compilation unit, is sampled by a process with activation frames of its own, which runs in the runtime&#39;s loop, as <code>fork forever begin @(event); c.sample(); end join_none</code> written in a function does: while one lives, every time slot of the design runs in that loop instead of the compiled scheduler. For a type of a package or the compilation unit this holds for every instance, a module&#39;s declaration <code>p::cg c = new;</code> included. That process holds the instance for the rest of the simulation: an object whose class embeds a covergroup with a clocking event is never collected once its constructor ran. A covergroup with a clocking event that nothing constructs costs nothing. Covergroups are not available in the browser (WASI) build, which has no heap.</li><li><strong>Host clocks.</strong> <code>Simulation::add_clock</code> and <code>Simulation::schedule</code> move an event signal: a clock or asynchronous reset of an edge-sensitive <code>always</code>, or a one-bit input of a top-level module that a process waits for. A process waits for the input its event control names (<code>@(posedge clk)</code>, <code>@(clk)</code>) or its <code>wait</code> condition reads: in the top module itself, by a hierarchical name, or through port connections and continuous assignments that copy the whole signal unchanged. For any other signal <code>schedule</code> returns <code>NotAnEvent</code> and <code>add_clock</code> does nothing: an input read only as data, an <code>iff</code> condition, a multi-bit input, and the operands of an event expression such as <code>@(posedge (clk &amp; en))</code> are driven with <code>modify</code> between the runs. With several top-level modules, <code>named_events()</code> names the events of each top from it (<code>hdl_top.clk</code>), and <code>add_clock_by_id</code> and <code>schedule_by_id</code> move them. An event signal cannot be forced from the host: <code>force_signals</code> rejects a waited input as it rejects a clock. A clock on a waited input that another event is computed from (a gated clock, an inverted reset) is not compiled into the scheduler&#39;s time slots, so each of its edges is a step of the host.</li><li><strong>Termination.</strong> <code>final</code> procedures run once on <code>$finish</code>, <code>$fatal</code>, or an explicit <code>Simulation::finish()</code>; an idle <code>step()</code> or the end of <code>run_until()</code> does not terminate the reusable Rust simulation. No scheduled events run afterwards, so a nonblocking assignment made directly in a <code>final</code> procedure never applies its queued update, and detached <code>fork … join_none</code> children declared in a <code>final</code> procedure are initialized but never start. <code>$stop</code> in an <code>initial</code> block suspends the simulation (<code>is_stopped()</code> is set and the next call continues); in an <code>always</code> process it is reported as <code>RuntimeEvent::Stop</code>, as <code>$finish</code> is <code>RuntimeEvent::Finish</code>. Batch hosts without an interactive mode, such as the VPI host, end the run at <code>$stop</code>. A checkpoint cannot be taken while suspended (<code>CheckpointError::Stopped</code>).</li><li><strong>Reports.</strong> <code>$info</code>, <code>$warning</code>, <code>$error</code>, and <code>$fatal</code> — including the default <code>$error</code> of an assertion without a fail action — are delivered to the host as <code>RuntimeEvent::Report</code> with severity, message, file, line, scope, and simulation time. Only <code>$error</code> and <code>$fatal</code> fail a <code>celox</code> run; <code>$fatal</code> also ends the simulation.</li><li><strong>Top-level modules.</strong> A simulation runs the top module it names. A design with several top-level modules (23.3.1), such as a testbench&#39;s <code>hdl_top</code> and <code>hvl_top</code>, runs them together when Rust&#39;s <code>SimulatorBuilder::tops</code> or a repeated <code>celox run --top</code> names them, each as an instance of its own name under <code>$root</code>, with its ports unconnected. Hierarchical names, <code>%m</code>, waveform scopes and the VPI and reflection hierarchy then start at a top (<code>hdl_top.dut</code>, <code>$root.hdl_top.dut</code>): each top is a root scope, as <code>vpi_iterate(vpiModule, NULL)</code> returns them. Signals are named from a top, as <code>signal(&quot;hdl_top.clk&quot;)</code> or <code>child_signal(&amp;[(&quot;hdl_top&quot;, 0)], &quot;clk&quot;)</code>, and so are forced and live signals. The design&#39;s tops are the selected modules: <code>PreserveTopPorts</code> keeps the ports of each, <code>named_signals()</code> names each top&#39;s signals from it (<code>hdl_top.clk</code>), <code>named_hierarchies()</code> gives each top&#39;s hierarchy, and <code>named_hierarchy()</code> is <code>$root</code> with the tops as its children. Several tops require SystemVerilog sources only and take no parameter overrides.</li><li><strong>Observable names.</strong> Interfaces are expanded into the modules that use them: a member <code>m</code> of interface instance <code>h</code> becomes the signal <code>h$m</code>, an interface port at the top becomes ports such as <code>bus$data</code>, and a module with a generic <code>interface</code> port is copied per connected interface as <code>M$I</code>. Instance array elements are addressed by their declared index (<code>dut.u[3]</code>, <code>child_signal(&amp;[(&quot;u&quot;, 3)], &quot;y&quot;)</code>). A package variable is named <code>p::v</code> and a compilation-unit variable <code>$unit::v</code> in <code>sim.signal(…)</code>. Hierarchical names can address signals, including <code>string</code> variables, in both SystemVerilog code and the host API.</li><li><strong>Heap and checkpoints.</strong> Strings, class objects, containers, and the objects <code>process::self()</code> returns live in a heap collected between time slots and after each <code>tick</code>; a <code>string</code>, class handle, <code>process</code> handle, or virtual interface is stored like a 32-bit integer. A process that ended keeps its status for as long as a <code>process</code> handle names it, and its storage is reused once the heap has collected every such handle. Core checkpoints (<code>checkpoint()</code> / <code>restore()</code>) preserve heap objects, fork children, process handles, random streams, pending strobe/monitor state, and deferred assertion queues. Portable state files are narrower: saving fails while any variable holds a class object, semaphore, mailbox, or exposed <code>process</code> handle, while a process waits for a named event or a current-slot trigger is still visible to <code>triggered</code>, while strobe output is pending, and for designs with file I/O, source VCD controls, or monitor tasks. Non-null class objects or dynamic containers, and nonempty string/object values in pending NBA writes, host writes, or event-wait baselines, likewise require a core checkpoint. Native images and serialized checkpoints from earlier heap or container layouts must be regenerated.</li><li><strong>Loop progress.</strong> A run-time loop in <code>always_ff</code> that stops making progress reports a runtime error naming its loop variable.</li><li><strong>Memory files.</strong> <a id="memory-files"></a> <code>$readmemh</code> and <code>$readmemb</code> read their file when they execute (21.4), never when the design is compiled, so compiled code, a JIT cache, and native images see the file as it is then. A load in an <code>initial</code> block that neither waits nor reads design state before it runs when each <code>Simulator</code> or <code>Simulation</code> instance is created, in both APIs; any other load runs at its statement, in <code>always_ff</code> at every activation and in <code>always_comb</code> whenever the block runs. A relative name is looked up in the working directory of the simulating process. The word-count warning and the errors of a load are <code>RuntimeEvent::Report</code>s; an error terminates the load, keeping the words loaded before it, and the simulation continues. An <code>initial</code> block that reads loaded words afterwards runs as a process. For the inferred-latch check of <code>always_comb</code>, a load assigns all the words it may load. An associative array is loaded when its indices are integral values of at most 64 bits and its elements packed values of at most 64 bits (21.4.1), always at its statement: each word creates or replaces the element of its address, which is the index&#39;s bit pattern (<code>@fffffffe</code> is the <code>int</code> index -2, as in Verilator). Without addresses in the call, a file address may name any index; an address or word that is no member of an enumerated index or element type is an error. An index that selects the array, as in <code>banks[i++]</code>, must have no effect. Dynamic arrays and queues are not loaded.</li></ul><h2 id="mixed-language" tabindex="-1">Mixing Veryl and SystemVerilog <a class="header-anchor" href="#mixed-language" aria-label="Permalink to &quot;Mixing Veryl and SystemVerilog {#mixed-language}&quot;">​</a></h2><p>Mixed designs are a Celox feature, not part of the standard. <code>Simulator::from_mixed_sources</code> (or <code>Simulation::from_sources(veryl).with_sv_sources(sv)</code>) combines both source lists. Veryl instantiates an SV module with <code>$sv::Module</code>; SV refers to a Veryl module or interface by its emitted name (<code>prj_Module</code>, or <code>Module</code> with <code>omit_project_prefix</code>; the project is <code>prj</code> without a <code>Veryl.toml</code>).</p><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported across boundary</th><th>Not supported across boundary</th></tr></thead><tbody><tr><td><strong>Modules and ports</strong></td><td>Either language as top; bidirectional hierarchy crossing; module parameters and plain signal ports</td><td>—</td></tr><tr><td><strong>Interfaces and functions</strong></td><td>Interfaces and <code>input</code> / <code>output</code> modports crossing in both directions</td><td>Cross-language interface function calls; function <code>import</code> / <code>export</code> modports; interface header functions with statement bodies the contract cannot express (such as loops), header-dependent formal or return widths, declaration casts whose target size depends on interface parameters, and constant functions that cannot be lowered symbolically <em>(these remain available within a single language)</em></td></tr></tbody></table><h2 id="dpi-c-imports" tabindex="-1">DPI-C imports <a class="header-anchor" href="#dpi-c-imports" aria-label="Permalink to &quot;DPI-C imports {#dpi-c-imports}&quot;">​</a></h2><p>A design can call C functions declared with <code>import &quot;DPI-C&quot;</code>. <code>celox run</code> links the shared libraries named by <code>--dpi-lib PATH</code> (repeatable) and by <code>dpi_libs</code> in <code>celox.toml</code>. In the Rust API, DPI-C registration is a host API of the builder:</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;C&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> c_add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { x</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wrapping_add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(y) }</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// SAFETY: `c_add` and the functions of libmodel.so have the signatures</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// their imports declare.</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> mut</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sim </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> unsafe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Simulator</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">from_sv_sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vec!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[(source, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;top.sv&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))], </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Top&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dpi_function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;c_add&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, c_add </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ())</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dpi_library</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;libmodel.so&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Each import is linked by its C name at build time: <code>dpi_function</code> registrations are searched first, then <code>dpi_library</code> libraries in order; an unresolved name fails the build with a <code>Dpi</code> error. Both methods are <code>unsafe</code>, because Celox cannot check that a C function matches its import. <code>allow_unlinked_dpi_for_elaboration()</code> builds a design despite unresolved imports, for an elaboration that never runs it (the sv-tests runner&#39;s elaboration mode, which links no C code as other tools&#39; does not): a call of such an import is a run-time error that names the import and says it was elaborated without its C body. It is off unless requested; simulation and every other build keep the error.</p><table tabindex="0"><thead><tr><th>Aspect</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td><strong>Declaration and call site</strong></td><td><code>import &quot;DPI-C&quot;</code> functions, including <code>context</code> imports (35.5.3), declared in a module, package, or <code>$unit</code> scope, called from <code>initial</code>, <code>always</code> (including <code>always @*</code>), <code>always_ff</code>, and subroutines they call</td><td>Tasks; calls from continuous assignments or <code>always_comb</code>; using the C scope API (<code>svGetScope</code>, <code>svSetScope</code>, <code>svGetNameFromScope</code>, <code>svGetScopeFromName</code>, user data) or calling exported SV subroutines inside <code>context</code> imports (libraries using those symbols fail to load with an unresolved-symbol error)</td></tr><tr><td><strong>Arguments and return types</strong></td><td>Up to 16 arguments (<code>input</code>, <code>output</code>, or <code>inout</code>); <code>bit</code>, <code>logic</code> (<code>svBit</code> / <code>svLogic</code>), <code>byte</code>, <code>shortint</code>, <code>int</code>, <code>longint</code> (signed or unsigned), <code>chandle</code>, <code>string</code> (<code>const char *</code>), packed arrays of <code>bit</code>/<code>logic</code>/<code>reg</code>, <code>integer</code>, and <code>time</code> (<code>svBitVecVal</code> / <code>svLogicVecVal</code> words); results of the types before packed arrays, or <code>void</code> (35.5.5)</td><td>More than 16 arguments; <code>real</code>, <code>shortreal</code>, named types (<code>typedef</code>, enums, structs), and unpacked or open arrays</td></tr><tr><td><strong><code>export &quot;DPI-C&quot;</code> (35.7)</strong></td><td>Declarations accepted and checked</td><td>Calling exported SV functions from C (see <code>context</code> import scope API restriction above)</td></tr></tbody></table><p>An <code>output</code> or <code>inout</code> argument is a pointer to its C type (a pointer to <code>const char *</code> for <code>string</code>). A string or packed array passed to the function is valid until it returns; a string it returns or writes to an <code>output</code> is copied when it returns. In two-state simulation, unknown bits a function writes to a <code>logic</code> argument read as zero. An <code>always @*</code> block that calls an import runs when what it reads changes (9.4.2.2) and no more often: a C function whose result changes without a change of its SystemVerilog arguments is not called again until one changes.</p><p>UVM&#39;s C library functions are provided by Celox and shadow any user implementation of the same name. The <code>uvm_re_*</code> functions use the Rust <code>regex</code> crate, whose syntax differs from POSIX extended regular expressions in rare constructs; <code>uvm_dpi_get_next_arg_c</code> returns <code>celox</code> followed by the plusargs and <code>uvm_dpi_get_tool_name_c</code> returns <code>Celox</code>. The <code>uvm_hdl_*</code> and <code>uvm_polling_*</code> functions return 0 or <code>null</code>, so UVM reports those facilities as unavailable. UVM 1.2&#39;s <code>uvm_re_match</code>, <code>uvm_glob_to_re</code>, <code>uvm_dump_re_cache</code>, <code>uvm_dpi_regcomp</code>, <code>uvm_dpi_regexec</code>, and <code>uvm_dpi_regfree</code> are provided too. Their reports (<code>UVM/DPI/REGEX_INV</code>, <code>UVM/DPI/REGEX_MAX</code>, <code>UVM/DPI/REGCOMP</code>, and the cache message) go through the function the UVM package exports for them, <code>m__uvm_report_dpi</code>, as UVM&#39;s C library makes them, so they count as UVM reports; the text after <code>invalid glob or regular expression</code> is the <code>regex</code> crate&#39;s reason, not <code>regerror</code>&#39;s.</p><h2 id="systemverilog-emitted-by-veryl" tabindex="-1">SystemVerilog emitted by Veryl <a class="header-anchor" href="#systemverilog-emitted-by-veryl" aria-label="Permalink to &quot;SystemVerilog emitted by Veryl {#systemverilog-emitted-by-veryl}&quot;">​</a></h2><p>The Veryl conformance suite also runs against the SystemVerilog that Veryl emits. The cases that remain excluded are:</p><ul><li>Veryl emits invalid SystemVerilog for an array literal that mixes positional items with <code>default:</code> (<code>&#39;{a, default: b}</code>).</li><li>Designs that opt into Veryl function calls with output arguments or side effects in <code>always_ff</code> have no SystemVerilog equivalent and are not emitted.</li><li>Testbench modules (<code>initial</code> blocks with clocking and <code>$finish</code> scheduling, hierarchical assignments) are not emitted as simulatable SystemVerilog modules.</li></ul>',106)])])}const m=o(n,[["render",r]]);export{p as __pageData,m as default};
